window.QUESTIONS = [{"id":"o1","t":"tzi","q":"Який фізичний пристрій використовується для повного екранування приміщення від зовнішніх та внутрішніх електромагнітних полів?","a":["Клітка Фарадея (суцільне або сітчасте металеве екранування із заземленням)","Ємнісний фільтр-обмежувач (конденсаторна батарея з індуктивною розв'язкою мережі живлення)","Ізолюючий трансформатор із подвійною обмоткою та електростатичним екраном між обмотками","Генератор просторового шуму з антенами, розташованими по периметру приміщення"],"g":"g0"},{"id":"o2","t":"tzi","q":"Що таке контрольована зона (КЗ) у сфері технічного захисту інформації?","a":["Простір навколо об'єкта, де виключено неконтрольоване перебування сторонніх осіб та автотранспорту і забезпечується режимний контроль","Територія, яка охороняється вахтою та відеоспостереженням, де зберігаються лише документи з грифом «Таємно»","Межа, за якою рівень сигналу ПЕМІН перевищує нормативне значення і потребує екранування обладнання","Частина мережі організації, де розміщені публічні сервери і яка відокремлена від внутрішньої мережі міжмережевим екраном"]},{"id":"o3","t":"tzi","q":"Що є метою проведення спеціальних досліджень (спецдосліджень) технічних засобів обробки інформації?","a":["Інструментальне вимірювання рівнів випромінювань ПЕМІН, визначення зони безпеки R2 та перевірка наявності можливих закладних пристроїв","Оцінка продуктивності технічних засобів та підтвердження їхньої відповідності вимогам енергоспоживання й електробезпеки","Перевірка програмного забезпечення на відсутність вразливостей і сертифікація криптографічних бібліотек у складі системи","Визначення категорії конфіденційності оброблюваної інформації та розроблення правил розмежування доступу для користувачів комплексу"]},{"id":"o4","t":"tzi","q":"Через який фізичний ефект виникає загроза витоку акустичної мовної інформації по акустоелектричному каналу в допоміжних технічних засобах (телефони, динаміки, датчики пожежної сигналізації)?","a":["Мікрофонний ефект: перетворення звукових коливань повітря на електричні сигнали внаслідок вібрації деталей елементної бази","Ефект електромагнітної індукції: наведення струму в сигнальних провідниках сусідніх ліній при протіканні змінного струму","Тепловий ефект: зміна опору провідників під дією звукового тиску та модуляція струму живлення мовним сигналом","Акустична ємнісна розв'язка: перетворення електричних імпульсів ліній зв'язку у механічні коливання корпусів приладів"],"g":"g2"},{"id":"o5","t":"tzi","q":"Який технічний пристрій застосовується для захисту віконних шибок від лазерного та стетоскопічного прослуховування?","a":["Віброзбуджувачі (п'єзовібратори), закріплені на склі, що випромінюють маскувальний акустичний шум","Інфрачервоні ліхтарі-випромінювачі, спрямовані на скло зсередини приміщення для засвічення лазерного приймача","Феритові поглинаючі накладки на оправу вікна, що гасять електромагнітні коливання, викликані голосом","Мережеві фільтри на кабелі живлення оконних електроприводів, що блокують акустичні наводки"],"g":"g1"},{"id":"o6","t":"tzi","q":"Як запобігти витоку інформації з екранів моніторів через оптичний канал (підглядання у вікна за допомогою біноклів або телевізорів)?","a":["Встановленням матових штор, жалюзі, світлозахисних плівок та правильним розташуванням моніторів спиною до вікон","Розміщенням на підвіконнях генераторів просторового шуму та збільшенням яскравості екранів у денний час","Застосуванням екранованих кабелів для підключення моніторів і встановленням феритових фільтрів на відеолінії","Заміною електронно-променевих моніторів на рідкокристалічні та вимкненням звуку на робочих станціях під час обробки даних"]},{"id":"o7","t":"tzi","q":"Який фізичний принцип використовується в екранованих камерах та серверних шафах для локалізації побічних електромагнітних випромінювань (ПЕМІН)?","a":["Принцип суцільного електромагнітного екранування замкненою електропровідною оболонкою (клітка Фарадея) з якісним заземленням","Принцип зашумлення: випромінювання широкосмугової завади в діапазоні частот ПЕМІН для зниження відношення сигнал/шум","Принцип гальванічної розв'язки: розділення ланцюгів живлення та сигналу трансформаторами й оптронами без застосування екрана","Принцип просторового рознесення: розміщення засобів на відстані, більшій за радіус зони R2, без застосування металевих оболонок"],"g":"g0"},{"id":"o8","t":"tzi","q":"Для протидії якому технічному каналу витоку мовної інформації на віконне скло та труби опалення у виділених приміщеннях встановлюють п'єзоелектричні віброперетворювачі (віброзбуджувачі)?","a":["Для захисту від лазерних акустичних систем підслуховування та електронних стетоскопів шляхом генерації маскуючого вібраційного шуму","Для захисту від радіозакладок у системах опалення шляхом генерації завад у радіодіапазоні над трубами","Для захисту від підключення до телефонної лінії шляхом подачі високовольтних імпульсів у ланцюги електроживлення будівлі","Для захисту від візуального спостереження через вікна шляхом вібрації скла, що розмиває зображення на моніторах"],"g":"g1"},{"id":"o9","t":"tzi","q":"У чому полягає явище мікрофонного ефекту у допоміжних технічних засобах (ДТЗ)?","a":["Звукові коливання тиснуть на радіодеталі (керамічні конденсатори, котушки), генеруючи паразитний електричний сигнал мови у дротах ліній живлення чи сигналізації","Електромагнітне поле високої частоти нагріває радіодеталі та змінює їхні параметри, що модулює струм у дротах ліній зв'язку","Радіоелементи випромінюють побічні сигнали на гармоніках тактової частоти, які поширюються в ефір і виявляються радіоприймачем","Звуковий тиск стискає ізоляцію кабелів і змінює їхню ємність, внаслідок чого мовний сигнал одразу з'являється в мережі Ethernet"],"g":"g2"},{"id":"o10","t":"tzi","q":"Як зловмисники можуть дистанційно знімати мовну інформацію з кабінету без проникнення всередину через віконне скло?","a":["За допомогою лазерного мікрофона, що реєструє мікровібрації віконного скла під дією голосу","За допомогою направленого мікрофона, що реєструє електромагнітні коливання від проводів під склом","За допомогою тепловізора, що фіксує зміну температури скла під час розмови та перетворює її на мовний сигнал","Шляхом аналізу відбитого радіолокаційного сигналу від металевої фурнітури вікон, що змінюється від звукового тиску"]},{"id":"o11","t":"tzi","q":"Що в методиках технічного захисту інформації (ТЗІ) від ПЕМІН означає параметр «Зона R2»?","a":["Максимальна відстань від джерела випромінювання (ОТЗ), за межами якої відношення інформативного сигналу до шуму стає настільки малим, що перехоплення інформації технічними розвідками є неможливим","Мінімальна відстань від джерела випромінювання до найближчої межі контрольованої зони, за якої допускається розміщення відкритих технічних засобів","Радіус зони, в межах якої рівень акустичного тиску мови перевищує 30 дБ і можливе її прослуховування стетоскопами та мікрофонами","Відстань між двома технічними засобами обробки інформації, за якої виникають взаємні наведення та перехресні завади в лініях живлення"]},{"id":"o12","t":"tzi","q":"На якому фізичному явищі базується принцип роботи нелінійного локатора (NLJD), що використовується під час спеціальних перевірок приміщень на наявність прихованих підслуховуючих пристроїв («жучків»)?","a":["Опромінення об'єктів зондуючим сигналом високої частоти та прийом відбитих сигналів на вищих гармоніках (2-й та 3-й) від p-n переходів напівпровідникових радіодеталей навіть у вимкненому стані","Випромінювання зондувального сигналу в інфрачервоному діапазоні та реєстрація теплових відбитків від працюючих мікросхем підслуховуючих пристроїв","Прийом власних радіовипромінювань працюючого «жучка» на його несучій частоті з наступним визначенням координат методом тріангуляції","Генерація низькочастотного магнітного поля та реєстрація вихрових струмів у металевих корпусах закладних пристроїв, як у металодетекторі"],"g":"g3"},{"id":"o13","t":"tzi","q":"У чому полягає суть методу високочастотного нав'язування (ВЧ-нав'язування) у телефонні чи радіолінії?","a":["Подача зондувального високочастотного сигналу в лінію, його модуляція елементами мікрофона за рахунок нелінійностей і прийом промодульованого сигналу назад","Підключення до лінії генератора широкосмугового шуму, що маскує мовні сигнали, які передаються телефонним каналом зв'язку","Подача у лінію постійної напруги підвищеного рівня для виявлення паралельного підключення прихованих апаратів за зміною струму й опору","Накладання на лінію низькочастотного тонального сигналу для автоматичного відключення мікрофона телефонного апарата під час відсутності розмови"]},{"id":"o14","t":"tzi","q":"До якої категорії методів технічного захисту належить застосування просторових генераторів шуму (шумотронів)?","a":["Активні заходи (маскування інформативного сигналу штучним шумом)","Пасивні заходи (екранування та заземлення технічних засобів)","Організаційні заходи (режим доступу та контроль відвідувачів)","Виявлювальні заходи (пошук закладних пристроїв нелінійним локатором)"]},{"id":"o15","t":"tzi","q":"Чому для живлення секретної обчислювальної техніки встановлюють спеціальні завадозахисні мережеві фільтри (наприклад, ФСП)?","a":["Для блокування проникнення інформативних високочастотних сигналів ПЕМІН у загальну мережу електроживлення будівлі","Для підвищення напруги в мережі та компенсації просідань, що виникають під час запуску потужного обладнання","Для забезпечення безперебійного живлення комп'ютерів при короткочасних відключеннях напруги в міській мережі та захисту від перенапруг","Для перетворення змінного струму на постійний та зменшення пульсацій напруги, що спричиняють збої в роботі процесорів"]},{"id":"o16","t":"tzi","q":"Що є фізичним джерелом виникнення побічних електромагнітних випромінювань і наведень (ПЕМІН) в комп'ютерній техніці?","a":["Протікання високочастотних імпульсних струмів у мікросхемах та лініях зв'язку, які діють як паразитні антени","Нагрівання напівпровідникових переходів під час роботи процесора, що викликає хвилі теплового випромінювання в радіодіапазоні","Вібрація вентиляторів та жорстких дисків, яка перетворюється на електричні коливання в блоці живлення і кабелях","Взаємодія зовнішніх радіохвиль мобільних мереж із корпусом комп'ютера, що викликає перевипромінювання корисного сигналу"]},{"id":"o17","t":"tzi","q":"За яким фізичним принципом працює нелінійний локатор (Non-Linear Junction Detector) для пошуку прихованих підслуховуючих пристроїв («жучків»)?","a":["За реєстрацією вищих гармонік (2-ї та 3-ї) зондувального сигналу, що відбиваються від напівпровідникових p-n переходів електронних мікросхем","За реєстрацією зсуву частоти (ефект Доплера) відбитого сигналу від рухомих деталей підслуховуючих пристроїв, що працюють у режимі передачі","За вимірюванням часу затримки відбитого імпульсу від металевих предметів у стінах та визначенням їхньої форми за картиною відбиття","За прийомом власного випромінювання на основній частоті від мікросхем підслуховуючих пристроїв після попереднього їх нагріву зондуючим потоком"],"g":"g3"},{"id":"o18","t":"tzi","q":"З якою метою в системах ТЗІ використовуються генератори просторового електромагнітного шумового випромінювання (генератори шуму)?","a":["Для активного маскування інформативних побічних сигналів ПЕМІН широкосмуговим шумовим сигналом, що знижує відношення сигнал/шум у приймачах зловмисника","Для екранування приміщення від зовнішніх електромагнітних полів та запобігання проникненню радіохвиль із вулиці всередину контрольованої зони","Для виявлення працюючих радіозакладок за зміною фонового шуму в ефірі та автоматичного оповіщення служби безпеки про їх присутність","Для синхронізації тактових частот комп'ютерів у приміщенні, щоб усі побічні випромінювання потрапляли в одну смугу та легко фільтрувалися"]},{"id":"o19","t":"tzi","q":"Який тип завади використовується в акустичних генераторах мовного зашумлення для захисту конфіденційних переговорів?","a":["Мовоподібна завада (мова багатьох дикторів у протифазі, «мовний хор») або білий/рожевий шум","Імпульсна завада з великою шпаруватістю в діапазоні ультразвуку 20–40 кГц, непомітна для слуху людини","Гармонійна завада у вигляді чистого тону фіксованої частоти 1 кГц, що забезпечує найкраще маскування мови","Лінійно-частотно-модульована завада з девіацією 100 МГц, що випромінюється в радіодіапазоні"]},{"id":"o20","t":"crypto","q":"Які дві обов'язкові умови використовуються зловмисником для організації атаки DNS Amplification (посилення DNS-трафіку)?","a":["Підміна IP-адреси відправника на адресу жертви (IP Spoofing) через UDP та надсилання запитів до відкритих рекурсивних DNS-серверів (Open Resolvers)","Використання протоколу TCP для встановлення тривалих сесій з авторитетними DNS-серверами та надсилання запитів з реальної IP-адреси ботнета","Отруєння кешу DNS-резолвера підробленими відповідями та перенаправлення користувачів на сервери зловмисника шляхом підбору Transaction ID","Надсилання великої кількості запитів на неіснуючі піддомени авторитетного сервера жертви (Random Subdomain) з IP-адрес ботнета"]},{"id":"o21","t":"crypto","q":"На які 4 категорії (теми) поділено заходи безпеки (Controls) в редакції стандарту ISO/IEC 27002:2022?","a":["Організаційні (Organizational), Люди (People), Фізичні (Physical), Технологічні (Technological)","Превентивні (Preventive), Детективні (Detective), Коригувальні (Corrective), Компенсаційні (Compensating)","Управлінські (Management), Операційні (Operational), Технічні (Technical), Правові (Legal)","Ідентифікація (Identify), Захист (Protect), Виявлення (Detect), Реагування (Respond)"],"g":"g9"},{"id":"o22","t":"crypto","q":"Яка різниця у призначенні між центром моніторингу безпеки (SOC) та групою реагування (CSIRT/CERT)?","a":["SOC займається безперервним моніторингом та виявленням подій 24/7, тоді як CSIRT спеціалізується на розслідуванні та локалізації підтверджених інцидентів","SOC відповідає лише за розроблення політик безпеки та навчання персоналу, тоді як CSIRT здійснює повсякденний моніторинг мережевого трафіку","SOC є державним органом, що координує реагування на кібератаки на рівні країни, а CSIRT — внутрішнім підрозділом компанії з управління ІТ","SOC проводить виключно тестування на проникнення та аудит захищеності, а CSIRT відповідає за адміністрування міжмережевих екранів і антивірусів"]},{"id":"o23","t":"crypto","q":"Що позначає метрика MTBF (Mean Time Between Failures) для апаратних компонентів?","a":["Середній час безвідмовної роботи між поломками (показник надійності)","Середній час відновлення працездатності обладнання після поломки (показник ремонтопридатності)","Максимальний час, на який допускається зупинка апаратури без втрат для бізнесу","Середній термін експлуатації обладнання до його повного списання"]},{"id":"o24","t":"crypto","q":"Що визначає показник RPO (Recovery Point Objective)?","a":["Максимально допустимий обсяг втрачених даних у часовому вимірі (від останнього бекапу до збою)","Максимально допустимий час простою сервісу від моменту аварії до повного відновлення його роботи","Мінімальна кількість резервних копій, яку необхідно зберігати на різних носіях у різних локаціях","Часова точка в майбутньому, до якої організація планує завершити впровадження плану відновлення після аварій"]},{"id":"o25","t":"crypto","q":"Яку нову шосту функцію додано в оновлений фреймворк NIST CSF 2.0 у 2024 році?","a":["Govern (Врядування / Керування)","Assess (Оцінювання / Аудит)","Comply (Відповідність / Комплаєнс)","Learn (Навчання / Вдосконалення)"],"g":"g8"},{"id":"o26","t":"crypto","q":"Що таке атака фізичної соціальної інженерії «Tailgating» (Piggybacking)?","a":["Прохід зловмисника в закрите приміщення вслід за авторизованим співробітником без пред'явлення власної перепустки","Підслуховування телефонних розмов співробітників за допомогою прихованого мікрофона, підкинутого в приміщення разом із поштою","Розсилання листів із вкладеннями, що імітують повідомлення від керівництва, для змушування працівників перейти на шкідливий сайт","Пошук викинутих документів, носіїв та роздруківок у смітниках біля офісу з метою отримання конфіденційних відомостей"]},{"id":"o27","t":"crypto","q":"Яка стратегія обробки ризику обирається при купівлі страхового полісу від кіберінцидентів?","a":["Передача ризику (Risk Transfer / Sharing)","Уникнення ризику (Risk Avoidance)","Зменшення ризику (Risk Mitigation / Reduction)","Прийняття ризику (Risk Acceptance / Retention)"]},{"id":"o28","t":"crypto","q":"Яка базова формула розрахунку інформаційного ризику в стандартах ISO 27005 / NIST?","a":["Ризик = Загроза × Вразливість × Наслідки (збитки)","Ризик = Актив + Загроза − Контрзаходи (витрати на захист)","Ризик = Вартість активу ÷ Кількість засобів захисту × Час дії загрози","Ризик = Вразливість × Кількість користувачів + Фактичні збитки"]},{"id":"o30","t":"crypto","q":"Чим цільовий фішинг (Spear-phishing) відрізняється від масового спам-фішингу?","a":["Він ретельно персоналізується під конкретну особу чи компанію з використанням зібраних розвідданих (OSINT)","Він розсилається лише через SMS та месенджери, тоді як масовий фішинг використовує виключно електронну пошту","Він завжди містить шкідливе вкладення з вимагачем, тоді як масовий фішинг лише збирає облікові дані на підроблених сторінках","Він здійснюється телефоном із підміною номера, а не листами, і спрямований тільки на працівників банків та держустанов"]},{"id":"o31","t":"crypto","q":"Чому при розслідуванні інциденту збір оперативної пам'яті (RAM) виконується ДО вимкнення живлення комп'ютера?","a":["Через принцип черговості збору доказів (Order of Volatility): пам'ять RAM енергозалежна і втрачається при вимкненні","Через вимогу стандарту ISO 27001: оперативну пам'ять потрібно копіювати першою, бо вона містить зашифрований образ жорсткого диска","Через те, що після вимкнення живлення BIOS автоматично очищає журнали подій і стирає таблицю розділів на накопичувачі","Через те, що RAM має найбільший обсяг серед усіх носіїв і її аналіз потребує найбільше часу експертів"]},{"id":"o32","t":"crypto","q":"Що гарантує криптографічна властивість досконалої прямої таємності (Perfect Forward Secrecy, PFS) у протоколах захищеного зв'язку?","a":["Компрометація довготривалого закритого ключа сервера в майбутньому не дозволить зловмиснику розшифрувати раніше записаний минулий трафік попередніх сесій","Закритий ключ сервера автоматично змінюється після кожного рукостискання, що унеможливлює перехоплення сертифіката під час передавання","Неможливість атаки «людина посередині», бо клієнт і сервер додатково підписують кожен пакет сеансовим ключем із довготривалої пари","Шифрування трафіку лише симетричними алгоритмами, тому квантовий комп'ютер у майбутньому не зможе розкрити записаний обмін"],"g":"g4"},{"id":"o33","t":"crypto","q":"Що таке ланцюжок забезпечення збереженості доказів (Chain of Custody) у цифровій криміналістиці?","a":["Хронологічний документ, що фіксує кожну особу, час, мету та умови вилучення, передавання й аналізу цифрових доказів","Послідовність мережевих вузлів, через які пройшов шкідливий пакет від джерела атаки до цілі, зафіксована маршрутизаторами","Алгоритм обчислення ланцюжка хешів блоків даних, що забезпечує незмінність журналів подій у розподіленому реєстрі","Ієрархія сертифікатів від кореневого центру сертифікації до кінцевого користувача, що підтверджує автентичність підпису експерта"]},{"id":"o34","t":"crypto","q":"Що є головною метою регулярного навчання працівників кібергігієні (Security Awareness Training)?","a":["Зниження ризику успішних атак соціальної інженерії та фішингу шляхом формування культури безпеки","Заміна технічних засобів захисту, оскільки грамотні працівники самостійно виявляють і блокують усі мережеві вторгнення","Виконання формальної вимоги стандарту та отримання сертифікатів, що слугують основою для зниження страхових внесків","Перекладання повної відповідальності за інциденти на персонал, щоб звільнити керівництво від юридичних наслідків"]},{"id":"o35","t":"crypto","q":"Для чого у цифровому сертифікаті стандарту X.509 використовується розширення «Extended Key Usage» (EKU)?","a":["Для точного обмеження цільового призначення сертифіката (наприклад: Server Authentication, Client Authentication, Code Signing, Time Stamping)","Для визначення терміну дії сертифіката та переліку адрес, за якими можна завантажити список відкликаних сертифікатів (CRL)","Для вказівки додаткових доменних імен та IP-адрес, на які поширюється дія сертифіката, окрім основного імені (SAN)","Для задання допустимих криптографічних операцій відкритого ключа: цифровий підпис, шифрування ключів та узгодження ключів (Key Usage)"]},{"id":"o36","t":"crypto","q":"На якій математичній задачі базуються стандартизовані NIST постквантові алгоритми шифрування та підпису (наприклад, ML-KEM / CRYSTALS-Kyber та ML-DSA / CRYSTALS-Dilithium)?","a":["Задачі на евклідових ґратках (Lattice-based cryptography, зокрема Learning With Errors — LWE)","Факторизація великих складених чисел та обчислення дискретного логарифму в мультиплікативній групі скінченного поля","Складність декодування загальних лінійних кодів з виправленням помилок (code-based криптографія типу McEliece)","Обчислення дискретного логарифму на еліптичних кривих над простими полями та пошук ізогеній між кривими"]},{"id":"o37","t":"crypto","q":"Яка обов'язкова умова повинна виконуватися для формування саме Кваліфікованого електронного підпису (КЕП) на відміну від удосконаленого (УЕП) згідно із законодавством України?","a":["Особистий ключ повинен зберігатися виключно у засобі кваліфікованого електронного підпису (захищеному носії / токені / апаратному HSM)","Підпис повинен створюватися лише у присутності нотаріуса або адміністратора реєстрації, який особисто засвідчує кожну операцію підписання","Підписувач повинен мати паспорт громадянина України та ідентифікаційний код, а сертифікат — містити фотографію власника ключа","Особистий ключ повинен мати довжину щонайменше 4096 біт, а сертифікат видаватися лише державним центром сертифікації ключів"],"g":"g14"},{"id":"o38","t":"crypto","q":"Що таке індикатори компрометації (Indicators of Compromise — IoC) у кіберрозвідці?","a":["Артефакти та криміналістичні сліди в системі або мережі (хеші шкідливих файлів, IP C2-серверів, домени), що свідчать про вторгнення","Недоліки конфігурації та вразливості програмного забезпечення (відсутні оновлення, слабкі паролі), якими зловмисник може скористатися для вторгнення","Методи та процедури, за допомогою яких злочинна група планує та виконує атаку, зокрема тактики, техніки й інструменти (TTP)","Показники ефективності системи захисту, що розраховуються за кількістю виявлених і заблокованих інцидентів за звітний період"]},{"id":"o39","t":"crypto","q":"Яка перша фаза життєвого циклу реагування на інциденти за стандартом NIST SP 800-61?","a":["Підготовка (Preparation)","Виявлення та аналіз (Detection & Analysis)","Стримування, ліквідація та відновлення (Containment, Eradication & Recovery)","Післяінцидентна діяльність (Post-Incident Activity)"]},{"id":"o40","t":"crypto","q":"Чому режим шифрування AES-GCM (Galois/Counter Mode) є рекомендованим у сучасних протоколах (TLS, IPsec) замість класичного режиму AES-CBC?","a":["AES-GCM забезпечує автентифіковане шифрування з приєднаними даними (AEAD), гарантуючи одночасно конфіденційність та цілісність, і стійкий до атак Padding Oracle","AES-GCM використовує довший ключ (512 біт), ніж CBC, тому стійкий до квантового перебору й зовсім не потребує вектора ініціалізації","AES-GCM працює як потоковий шифр без nonce, тому допускає необмежене повторне використання одного ключа без втрати стійкості","AES-GCM застосовує лише гешування без шифрування, тому забезпечує цілісність, але конфіденційність потрібно додатково забезпечувати режимом CBC"],"g":"g5"},{"id":"o41","t":"crypto","q":"Яку криптографічну властивість геш-функції намагається порушити атакуючий під час атаки «днів народження» (Birthday Attack)?","a":["Стійкість до колізій (Collision Resistance: пошук будь-яких двох різних повідомлень m1 != m2, для яких H(m1) = H(m2))","Стійкість до пошуку прообразу (Preimage Resistance: за заданим гешем h знайти повідомлення m, для якого H(m) = h)","Стійкість до пошуку другого прообразу (Second Preimage: для заданого m1 знайти інше m2, для якого H(m1) = H(m2))","Лавинний ефект (Avalanche Effect: зміна одного біта вхідного повідомлення має змінювати приблизно половину бітів геш-значення)"]},{"id":"o42","t":"crypto","q":"У чому полягає основна відмінність Web Application Firewall (WAF) від традиційного мережевого міжмережевого екрану (NGFW L3/L4)?","a":["WAF спеціалізовано аналізує прикладний рівень (L7), виявляючи специфічні веб-атаки (SQLi, XSS, SSRF), декодуючи HTTP/HTTPS запити","WAF працює на мережевому рівні (L3) і фільтрує пакети за IP-адресами та портами, тоді як NGFW перевіряє вміст веб-запитів","WAF встановлюється лише на робочих станціях користувачів і блокує завантаження шкідливих програм, а NGFW захищає веб-сервери від SQLi","WAF виконує трансляцію адрес і маршрутизацію між VLAN, тоді як NGFW аналізує тільки заголовки TCP/UDP без вмісту сесій"],"g":"g6"},{"id":"o43","t":"crypto","q":"Яка основна перевага криптографії на еліптичних кривих (ECC, наприклад криві Ed25519, NIST P-256) над алгоритмом RSA?","a":["Забезпечення аналогічного рівня криптографічної стійкості при суттєво меншому розмірі ключа (наприклад, 256 біт ECC еквівалентно 3072 біт RSA), що зменшує накладні витрати на передачу та обчислення","Стійкість до атак на квантових комп'ютерах, бо задача дискретного логарифму на кривих не розв'язується алгоритмом Шора на відміну від факторизації в RSA","Відсутність потреби в генераторі випадкових чисел, оскільки ключі та підписи в ECC формуються детерміновано без додаткових параметрів у всіх схемах","Можливість шифрувати довільні великі обсяги даних безпосередньо відкритим ключем без використання симетричних шифрів, що неможливо в RSA"]},{"id":"o44","t":"crypto","q":"Який базовий принцип лежить в основі архітектури нульової довіри (Zero Trust Architecture, NIST SP 800-207)?","a":["«Ніколи не довіряй, завжди перевіряй»: жоден суб'єкт чи пристрій не має неявної довіри незалежно від мережевого розташування","«Довіряй, але перевіряй»: усі пристрої всередині корпоративного периметра вважаються безпечними, а перевірка потрібна лише для зовнішніх підключень","«Мінімум привілеїв за замовчуванням»: кожен користувач отримує лише ті права, які потрібні для його посади, і втрачає їх після звільнення","«Захист у глибину»: кілька послідовних рубежів — периметр, мережа, хост, застосунок — так що злам одного не відкриває доступ до даних"]},{"id":"o45","t":"crypto","q":"Що є головною метою аналізу впливу на бізнес (BIA) у системі управління безперервністю?","a":["Ідентифікація критичних бізнес-процесів організації та оцінка наслідків від їх зупинки у часі","Визначення переліку вразливостей інформаційних систем та оцінка ймовірності їх експлуатації зловмисниками","Розроблення покрокових інструкцій для відновлення серверів із резервних копій після апаратних збоїв","Перевірка відповідності діяльності працівників внутрішнім політикам і виявлення порушень вимог безпеки"]},{"id":"o46","t":"crypto","q":"Яка мета класифікації інформаційних активів в організації відповідно до ISO 27001?","a":["Забезпечення адекватного рівня захисту активів відповідно до їх цінності та критичності для бізнесу","Визначення переліку осіб, які мають право доступу до серверних приміщень, та порядку ведення журналів відвідувань","Розрахунок страхової вартості обладнання та програмного забезпечення для списання основних засобів на балансі","Відокремлення публічної інформації від службової для публікації на вебсайті організації у відкритому доступі"]},{"id":"o47","t":"crypto","q":"Який механізм дозволяє серверу захиститися від вичерпання черги незавершених TCP-з'єднань (SYN queue) під час атаки TCP SYN Flood без виділення пам'яті під напіввідкриті сесії?","a":["Використання механізму SYN Cookies","Використання механізму TCP Keepalive","Використання механізму Window Scaling","Використання технології Port Knocking"],"g":"g7"},{"id":"o48","t":"crypto","q":"Чому обчислення хешу SHA-256 цифрового носія є обов'язковим при вилученні речових доказів?","a":["Щоб довести, що під час копіювання та експертизи образ диску не зазнав жодних змін (доказ цілісності)","Щоб зашифрувати образ диску, оскільки SHA-256 є симетричним шифром і захищає докази від несанкціонованого читання","Щоб відновити видалені файли, адже геш-значення містить інформацію про стерті кластери файлової системи","Щоб прискорити копіювання даних, бо геш-значення дозволяє пропускати порожні сектори й зменшує розмір образу"]},{"id":"o49","t":"crypto","q":"Для чого проводиться аналіз розривів (Gap Analysis) під час підготовки до сертифікації за стандартом безпеки?","a":["Для порівняння поточного фактичного стану безпеки організації з вимогами стандарту та визначення необхідних заходів для досягнення відповідності","Для виявлення технічних вразливостей у мережі шляхом автоматичного сканування вузлів та складання переліку застосунків без оновлень","Для оцінювання фінансових втрат від можливого інциденту та розрахунку окупності інвестицій у засоби захисту інформації","Для перевірки кваліфікації працівників підрозділу ІТ та складання програми їх навчання за міжнародними сертифікаційними курсами"]},{"id":"o50","t":"kszi","q":"Яка кардинальна зміна безпеки була реалізована в протоколі TLS 1.3 (RFC 8446) порівняно з TLS 1.2?","a":["Вилучення статичного RSA-обміну ключами на користь обов'язкового ефемерного Діффі-Геллмана (PFS)","Перехід від асиметричної криптографії до виключно симетричних ключів, попередньо розподілених між усіма клієнтами та серверами","Заміна сертифікатів X.509 на самопідписані ключі, які клієнт довіряє автоматично при першому підключенні до сервера","Додавання обов'язкового шифрування заголовків IP-пакетів на мережевому рівні замість захисту лише даних транспортного рівня"],"g":"g10"},{"id":"o51","t":"kszi","q":"Чим протокол IPsec ESP відрізняється від AH?","a":["ESP забезпечує конфіденційність (шифрування) та цілісність, а AH лише цілісність без шифрування","AH забезпечує шифрування та цілісність, а ESP лише автентифікацію заголовків без захисту даних","ESP працює тільки в транспортному режимі, а AH — виключно в тунельному, і обидва забезпечують лише конфіденційність","ESP призначений для обміну ключами між вузлами, а AH — для узгодження алгоритмів, жоден із них не захищає дані користувача"]},{"id":"o52","t":"kszi","q":"Чим брандмауер веб-додатків (Web Application Firewall — WAF) відрізняється від мережевого екрана L4?","a":["WAF працює на рівні додатків (L7), аналізуючи вміст HTTP/HTTPS запитів на предмет SQLi, XSS та інших атак OWASP","WAF працює на транспортному рівні (L4), блокуючи підозрілі TCP-з'єднання за номерами портів і лічильниками SYN-пакетів","WAF відстежує стан сесій у таблиці та автоматично пропускає зворотний трафік, не аналізуючи вміст запитів застосунків","WAF встановлюється на комутаторі й ізолює VLAN за MAC-адресами, не звертаючи уваги на HTTP-запити та їх параметри"],"g":"g6"},{"id":"o53","t":"kszi","q":"Що відповідно до НД ТЗІ 2.5-005-99 являє собою «Профіль захисту» (Protection Profile) засобу обчислювальної техніки або ІКС?","a":["Уніфікований нормативний документ, що містить нормалізований перелік функціональних критеріїв безпеки та гарантій, які повинен задовольняти комплекс засобів захисту","Перелік конкретних апаратних та програмних засобів захисту, рекомендованих до закупівлі державним замовникам для побудови систем захисту","Документ власника системи, у якому описано загрози, модель порушника та організаційні заходи для конкретної автоматизованої системи","Сертифікат, що видається Держспецзв'язку виробнику за результатами експертизи програмного продукту захисту та підтверджує його якість"]},{"id":"o54","t":"kszi","q":"Хто несе персональну відповідальність за забезпечення збереження та нерозголошення парольної та ключової інформації користувача в автоматизованій системі з КСЗІ?","a":["Безпосередньо сам користувач, якому надано відповідні облікові реквізити та права доступу","Адміністратор безпеки, який створює облікові записи, видає паролі та контролює дотримання парольної політики","Керівник структурного підрозділу, співробітникам якого надано доступ до ресурсів автоматизованої системи","Служба захисту інформації організації, що розробляє політику безпеки та здійснює щоденний контроль"]},{"id":"o55","t":"kszi","q":"У чому різниця між списками контролю доступу DACL та SACL в операційній системі Windows?","a":["DACL визначає дозволи та заборони доступу користувачів, а SACL налаштовує аудит спроб доступу до об'єкта","DACL налаштовує аудит спроб доступу до об'єкта, а SACL визначає дозволи та заборони для користувачів і груп","DACL застосовується лише до файлів і папок NTFS, а SACL — до об'єктів реєстру та принтерів, функції в них однакові","DACL зберігає список користувачів, які успішно увійшли, а SACL — список заблокованих облікових записів у домені"]},{"id":"o56","t":"kszi","q":"Що є основним призначенням системи управління подіями інформаційної безпеки (SIEM)?","a":["Збір, нормалізація та кореляційний аналіз журналів подій з різних джерел у реальному часі для виявлення інцидентів","Автоматичне блокування шкідливих пакетів на периметрі мережі за сигнатурами без аналізу журналів і збереження подій","Сканування вузлів мережі на наявність вразливостей та формування звітів про відсутні оновлення безпеки","Централізоване керування обліковими записами користувачів та автоматичне надання прав доступу відповідно до посад"]},{"id":"o57","t":"kszi","q":"Яким чином протокол DNSSEC забезпечує захист клієнтів від атак спуфінгу та отруєння кешу DNS (DNS Cache Poisoning)?","a":["Криптографічним підписом ресурсних записів за допомогою цифрових підписів RRSIG та ланцюжка довіри через DS-записи","Шифруванням DNS-запитів між клієнтом і резолвером за протоколом TLS, що приховує їх від спостерігачів у мережі","Блокуванням відповідей з IP-адрес, що не належать авторитетним серверам, за списками, які оновлюються щодня","Обмеженням кількості запитів з однієї IP-адреси та випадковим вибором порту джерела при кожному запиті до резолвера"],"g":"g11"},{"id":"o58","t":"kszi","q":"Який тип сканування портів утиліти Nmap відправляє пакет з прапорцем SYN і закриває з'єднання RST-пакетом при отриманні SYN-ACK (Stealth scan)?","a":["SYN Stealth Scan (-sS)","TCP Connect Scan (-sT)","UDP Scan (-sU)","ACK Scan (-sA)"]},{"id":"o59","t":"kszi","q":"Які послуги безпеки оцінюються критерієм конфіденційності «КД» відповідно до НД ТЗІ 2.5-004-99?","a":["Розмежування доступу користувачів до інформації та захист від несанкціонованого ознайомлення","Виявлення фактів несанкціонованої модифікації інформації та забезпечення відкату змін у разі порушення","Забезпечення доступності ресурсів і відновлення працездатності системи після збоїв та відмов компонентів","Реєстрація подій, пов'язаних з безпекою, та забезпечення спостережності дій користувачів у системі"]},{"id":"o60","t":"kszi","q":"Яке покращення безпеки було впроваджено у протоколі TLS 1.3 порівняно з TLS 1.2?","a":["Видалення підтримки застарілих та небезпечних шифрів (RC4, DES, CBC, статичного RSA) та обов'язковий Perfect Forward Secrecy","Додавання підтримки алгоритмів RC4 та DES у режимі сумісності та перехід на 4-стороннє рукостискання з обов'язковою передачею сертифіката клієнта","Заміна протоколу TCP на UDP для всіх з'єднань і шифрування номерів портів, що приховує тип застосунку від спостерігачів","Перенесення функцій автентифікації на рівень IP із використанням ESP та відмова від сертифікатів X.509 на користь попередньо розподілених ключів"],"g":"g10"},{"id":"o61","t":"kszi","q":"У чому відмінність міжсережевого екрана зі збереженням стану (Stateful Inspection) від пакетного фільтра (Stateless)?","a":["Stateful екран відстежує стан сесій у таблиці трансляцій і автоматично пропускає зворотний трафік для легітимних з'єднань","Stateful екран перевіряє лише заголовки окремих пакетів за статичними правилами, тоді як Stateless аналізує вміст сесій","Stateful екран працює виключно на прикладному рівні й діє як проксі, тоді як Stateless транслює адреси та порти","Stateful екран зберігає журнали всіх пакетів на диску для подальшого аналізу, а Stateless не веде жодних журналів"]},{"id":"o62","t":"kszi","q":"Яку роль виконує квиток TGT (Ticket Granting Ticket) у протоколі Kerberos?","a":["Дозволяє клієнту звертатися до служби TGS за квитками до конкретних сервісів без повторного введення пароля","Містить пароль користувача у відкритому вигляді та передається серверу застосунку для перевірки автентичності клієнта","Підтверджує особу сервера перед клієнтом і шифрується ключем сервісного облікового запису застосунку (SPN)","Видається сервером застосунку після входу та використовується для відновлення пошкоджених сесій без звернення до контролера домену"]},{"id":"o63","t":"kszi","q":"Яка дія виконується комутатором за замовчуванням у режимі порушення Port Security «Shutdown»?","a":["Порт негайно переводиться у стан помилки (error-disabled) і припиняє передачу кадрів","Порт продовжує роботу, відкидаючи кадри з невідомих MAC-адрес, і лише збільшує лічильник порушень без жодних повідомлень","Порт продовжує передавати кадри, а комутатор надсилає SNMP-повідомлення та записує подію в журнал (режим Restrict)","Порт автоматично переводиться в іншу VLAN з карантинними серверами і чекає ручної перевірки адміністратором"]},{"id":"o64","t":"kszi","q":"Який тип порту у технології Private VLAN (PVLAN) має право взаємодіяти з усіма іншими портами, включаючи Isolated та Community порти?","a":["Promiscuous порт (змішаний)","Isolated порт (ізольований)","Community порт (спільнотний)","Trunk порт (магістральний)"]},{"id":"o65","t":"kszi","q":"Який найнадійніший первинний метод захисту від атак SQL-ін'єкція?","a":["Параметризовані запити (Prepared Statements) та ORM","Видалення лапок та спеціальних символів із введених користувачем даних","Використання міжмережевого екрана на периметрі мережі","Шифрування вмісту бази даних та резервних копій"]},{"id":"o66","t":"kszi","q":"Яка функція захисту комутаторів L2 запобігає атакам перехоплення трафіку через несанкціоновані анонси маршрутизатора в мережах IPv6 (Rogue Router Advertisement)?","a":["IPv6 RA Guard (Router Advertisement Guard)","DHCP Snooping (контроль DHCP-відповідей)","Dynamic ARP Inspection (DAI)","Port Security (обмеження кількості MAC-адрес)"]},{"id":"o67","t":"kszi","q":"У чому полягає небезпека міжсайтового скриптингу (Cross-Site Scripting — XSS)?","a":["Виконання зловмисного JavaScript у браузері жертви з можливістю крадіжки сесійних cookies та токенів","Впровадження SQL-команд у параметри запиту, що дозволяє зловмиснику читати та змінювати вміст бази даних на сервері","Виконання довільних системних команд на веб-сервері через вразливі функції обробки файлів, що надає доступ до оболонки","Перехоплення мережевого трафіку між браузером і сервером за відсутності HTTPS із розшифруванням паролів у відкритому вигляді"]},{"id":"o68","t":"kszi","q":"Який документ видається Адміністрацією Держспецзв'язку України за результатами успішного проходження державної експертизи КСЗІ, що підтверджує її готовність до введення в промислову експлуатацію?","a":["Атестат відповідності комплексної системи захисту інформації","Сертифікат відповідності засобу криптографічного захисту інформації","Ліцензія на провадження господарської діяльності у сфері ТЗІ","Висновок експертизи щодо стану криптографічного захисту інформації"],"g":"g12"},{"id":"o69","t":"kszi","q":"У чому полягає вразливість серверної підробки запитів (Server-Side Request Forgery — SSRF)?","a":["Атакуючий змушує вразливий бекенд-сервер відправити HTTP-запит до внутрішніх ресурсів (наприклад, до хмарних метаданих 169.254.169.254)","Атакуючий змушує браузер користувача надіслати запит до сайту, на якому той автентифікований, використовуючи його збережені cookies сесії","Атакуючий вводить SQL-код у поле форми, і сервер виконує його, повертаючи вміст таблиць бази даних у відповіді застосунку","Атакуючий вставляє скрипт у коментар, який зберігається на сторінці та виконується в браузерах усіх відвідувачів сайту"]},{"id":"o70","t":"kszi","q":"Що означає технологія Split Tunneling при використанні корпоративного VPN?","a":["Маршрутизація тільки корпоративного трафіку через шифрований тунель VPN, тоді як звичайний інтернет-трафік йде напряму через локального провайдера","Розділення VPN-тунелю на два канали з різними алгоритмами шифрування: один для даних, а інший — для керуючих повідомлень","Маршрутизація всього трафіку користувача через тунель VPN, включно з інтернет-запитами, з фільтрацією на корпоративному шлюзі","Одночасне підключення одного клієнта до кількох VPN-серверів для розподілу навантаження та підвищення швидкості"]},{"id":"o71","t":"kszi","q":"Яка технологія використовується для криптографічної перевірки права автономної системи (AS) анонсувати певний префікс IP-адрес для запобігання атакам BGP Hijacking?","a":["RPKI (Resource Public Key Infrastructure) та валідація походження маршруту (ROA)","DNSSEC (DNS Security Extensions) та перевірка ланцюжка довіри через DS-записи","BGP MD5-автентифікація сесій між сусідами та обмеження TTL пакетів (GTSM)","IPsec AH між усіма маршрутизаторами автономних систем та обмін сертифікатами"]},{"id":"o72","t":"kszi","q":"Як згідно з ДСТУ 3396.0-96 класифікуються загрози інформаційній безпеці за природою походження?","a":["Природні (стихійні лиха, збої) та штучні (антропогенні, спричинені діяльністю людини)","Внутрішні (з боку персоналу організації) та зовнішні (з боку сторонніх осіб і конкурентів)","Навмисні (атаки та диверсії) та випадкові (помилки користувачів і технічні несправності)","Технічні (апаратні, програмні) та організаційні (кадрові, правові, фізичні)"]},{"id":"o73","t":"kszi","q":"Що в КСЗІ визначає поняття «Правила розмежування доступу» (ПРД)?","a":["Частину політики безпеки, яка точно регламентує, які суб'єкти доступу (користувачі) та які права (читання, запис, виконання) мають стосовно яких об'єктів доступу (файли, бази даних, порти)","Перелік заходів, що визначає порядок видачі паролів і ключів користувачам, терміни їх дії та вимоги до складності комбінацій символів у системі","Документ, який описує модель порушника, перелік загроз та ймовірність їх реалізації для кожного ресурсу автоматизованої системи організації","Технічні специфікації міжмережевих екранів та систем виявлення вторгнень, що містять набори сигнатур та правила фільтрації мережевих пакетів"]},{"id":"o74","t":"kszi","q":"Хто затверджує «Положення про службу захисту інформації» та накази про призначення відповідальних осіб за ІБ в організації при створенні КСЗІ?","a":["Керівник організації (підприємства, установи)","Адміністрація Держспецзв'язку України після погодження проекту","Начальник служби захисту інформації організації","Головний інженер разом із начальником відділу кадрів"]},{"id":"o75","t":"kszi","q":"Чому апаратні ключі FIDO2 (наприклад, YubiKey) стійкі до фішингових атак на відміну від SMS-кодів або TOTP?","a":["Ключ прив'язує підпис автентифікації до точного доменного імені сайту (Origin binding) через криптографію відкритого ключа","Ключ генерує одноразовий шестизначний код кожні 30 секунд, який неможливо перехопити, оскільки він не передається мережею","Ключ шифрує пароль користувача на пристрої та зберігає його в захищеному чипі, тому зловмисник не може його ввести на фальшивому сайті","Ключ надсилає код підтвердження на мобільний номер власника через захищений канал оператора, що унеможливлює підміну SIM-картки"]},{"id":"o76","t":"kszi","q":"У чому полягає суть атаки Cross-Site Request Forgery (CSRF)?","a":["Змушування браузера автентифікованого користувача виконати небажану дію на цільовому сайті за рахунок збережених cookies","Впровадження шкідливого скрипту в сторінку сайту, який виконується в браузерах відвідувачів і викрадає дані їхніх сесій","Підміна відповідей DNS-сервера для перенаправлення користувача на фальшивий сайт, який імітує цільовий ресурс","Підбір ідентифікатора сесії користувача шляхом перебору можливих значень до отримання доступу до облікового запису"]},{"id":"o77","t":"kszi","q":"Який головний недолік сигнатурних систем виявлення вторгнень (Signature-based IDS)?","a":["Нездатність виявляти раніше невідомі атаки нульового дня (0-day) без наявності сигнатури","Надмірне навантаження на мережу через дублювання всього трафіку на сенсор і неможливість працювати на швидкості понад 100 Мбіт/с","Неможливість виявляти відомі атаки та шкідливе ПЗ, для яких сигнатури вже опубліковані виробниками","Високий рівень хибних спрацьовувань через навчання на трафіку, який вважається нормальним, і потреба в ручному налаштуванні"]},{"id":"o78","t":"kszi","q":"Що таке атака типу «VLAN Hopping» (Double Tagging)?","a":["Відправка кадру з двома тегами 802.1Q для несанкціонованого передавання трафіку в інший ізольований VLAN в обхід маршрутизатора","Підміна MAC-адреси шлюзу в таблиці ARP жертв для спрямування їх трафіку через пристрій зловмисника в межах одного VLAN","Переповнення таблиці MAC-адрес комутатора підробленими кадрами, після чого він працює як хаб і передає трафік усіма портами","Створення зловмисником підробленого DHCP-сервера, що видає клієнтам неправильну адресу шлюзу для перехоплення їхнього трафіку"]},{"id":"o79","t":"kszi","q":"Яка технологія комутаторів L2 запобігає атакам типу ARP Spoofing?","a":["Dynamic ARP Inspection (DAI) у поєднанні з DHCP Snooping","Port Security з обмеженням кількості MAC-адрес на порту","BPDU Guard разом із Root Guard на портах доступу","Storm Control з обмеженням широкомовного трафіку"]},{"id":"o80","t":"kszi","q":"Яка ключова відмінність TACACS+ від RADIUS у роботі з пакетами безпеки?","a":["TACACS+ шифрує все тіло пакета та розділяє функції автентифікації, авторизації та обліку (AAA), використовуючи TCP","TACACS+ шифрує лише пароль у пакеті, об'єднує автентифікацію й авторизацію в одному повідомленні та працює поверх UDP","TACACS+ є відкритим стандартом IETF, що передає атрибути у відкритому вигляді та підтримує лише облік без авторизації","TACACS+ працює виключно з бездротовими клієнтами за стандартом 802.1X і не підтримує керування доступом до мережевих пристроїв"]},{"id":"o81","t":"kszi","q":"Який секрет використовує зловмисник для генерації фальшивого квитка «Golden Ticket» в Active Directory?","a":["Хеш NTLM/пароль спеціального облікового запису krbtgt домену","Хеш NTLM облікового запису локального адміністратора контролера домену","Закритий ключ кореневого центру сертифікації підприємства (AD CS)","Пароль облікового запису комп'ютера, що виконує роль сервера застосунку"]},{"id":"o82","t":"kszi","q":"Який ідентифікатор події (Event ID) в журналі Security Windows свідчить про успішний вхід користувача в систему?","a":["4624","4625","4634","4672"]},{"id":"o83","t":"kszi","q":"Який захисний механізм використовується серверами для протидії атакам типу SYN Flood без збереження стану напіввідкритих з'єднань?","a":["SYN Cookies","Nagle's Algorithm (алгоритм Нагля)","TCP Fast Open","ICMP Rate Limiting"],"g":"g7"},{"id":"o84","t":"net","q":"Який тип запису DNS використовується для зіставлення IP-адреси з доменним іменем (Reverse DNS lookup)?","a":["PTR","CNAME","MX","SRV"]},{"id":"o85","t":"net","q":"Що означає встановлений біт SUID (Set User ID) на виконуваному файлі в Linux?","a":["Програма виконується з привілеями власника файлу (наприклад, root), а не користувача, що її запустив","Програма виконується з привілеями групи-власника файлу, а не користувача, і доступна для запуску лише членам цієї групи","Файли в каталозі з цим бітом можуть видаляти лише їх власники, навіть якщо інші мають права запису в каталог","Програма завжди запускається в ізольованому середовищі chroot з обмеженими правами та без доступу до мережі й пристроїв"]},{"id":"o86","t":"net","q":"Які механізми ядра Linux забезпечують ізоляцію та ліміти ресурсів контейнерів?","a":["Namespaces (ізоляція видимості) та cgroups (ліміти ресурсів)","SELinux (ізоляція файлів) та iptables (ліміти трафіку)","chroot (ізоляція мережі) та sudo (ліміти ресурсів)","Seccomp (ізоляція дисків) та auditd (ліміти процесів)"],"g":"g13"},{"id":"o87","t":"net","q":"Яку загрозу безпеці DNS нейтралізує технологія DNSSEC (DNS Security Extensions)?","a":["Підробку та отруєння кешу DNS (DNS Cache Poisoning / Spoofing) шляхом перевірки цифрових підписів записів","Перехоплення DNS-запитів провайдером або спостерігачем у мережі, шляхом шифрування каналу між клієнтом і резолвером","Атаки типу DNS Amplification, обмежуючи розмір відповідей та вимагаючи автентифікації клієнтів перед обробкою запитів","Тунелювання даних через DNS-запити, виявляючи аномально довгі імена та високу частоту запитів до одного домену"],"g":"g11"},{"id":"o88","t":"net","q":"Як працює біт NX (No-Execute) / DEP?","a":["Забороняє виконання процесором інструкцій зі сторінок пам'яті з даними (стек, купа)","Забороняє запис у сторінки пам'яті з кодом програми та бібліотек, щоб зловмисник не міг змінити інструкції","Випадково змінює розташування модулів в адресному просторі, щоб зловмисник не знав адрес для переходу","Перевіряє цілісність адреси повернення функції перед виходом з неї та завершує процес у разі зміни"]},{"id":"o89","t":"net","q":"Що таке сторінкове переривання (Page Fault) в операційній системі?","a":["Подія, коли процес звертається до віртуальної сторінки пам'яті, якої наразі немає у фізичній RAM (вимагається завантаження зі свопу)","Помилка процесора при спробі виконати недозволену інструкцію, що призводить до негайного завершення процесу з аварійним повідомленням","Подія, коли процес намагається записати дані за межами виділеного масиву, внаслідок чого пошкоджується сусідня змінна","Переповнення таблиці сторінок ядра, коли не вдається виділити пам'ять для нового процесу, і система зупиняється (kernel panic)"]},{"id":"o90","t":"net","q":"Який протокол стеку TCP/IP використовують утиліти ping та traceroute?","a":["ICMP (Internet Control Message Protocol)","ARP (Address Resolution Protocol)","IGMP (Internet Group Management Protocol)","SNMP (Simple Network Management Protocol)"]},{"id":"o91","t":"net","q":"У чому перевага гіпервізорів 1-го типу (Type 1 bare-metal) над Type 2 з точки зору безпеки?","a":["Працюють безпосередньо на «залізі» без хостової ОС, що зменшує поверхню атаки","Працюють усередині хостової ОС як звичайний застосунок, що дозволяє використовувати її драйвери й антивірус для захисту","Не потребують ізоляції віртуальних машин, оскільки кожна ВМ отримує повний доступ до пам'яті сусідніх ВМ","Автоматично шифрують усі диски гостьових систем та принципово виключають можливість втечі з віртуальної машини"]},{"id":"o92","t":"net","q":"Яку довжину має адреса в протоколі IPv6 у порівнянні з IPv4?","a":["IPv6 має 128 біт (16 байт) проти 32 біт у IPv4","IPv6 має 64 біти (8 байт) проти 32 біт у IPv4","IPv6 має 256 біт (32 байти) проти 64 біт у IPv4","IPv6 має 96 біт (12 байт) проти 48 біт у IPv4"]},{"id":"o93","t":"net","q":"Яка середня часова складність алгоритму швидкого сортування (QuickSort)?","a":["O(n log n)","O(n²)","O(n)","O(log n)"]},{"id":"o94","t":"net","q":"Яка середня часова складність операції пошуку за ключем у хеш-таблиці?","a":["O(1)","O(n)","O(log n)","O(n log n)"]},{"id":"o95","t":"net","q":"Що гарантує властивість Атомарності (Atomicity) у реляційних СКБД?","a":["Транзакція виконується або повністю, або жодна з її дій не фіксується у базі даних (All or Nothing)","Результати успішної транзакції зберігаються на диску навіть після збою живлення чи перезапуску сервера бази даних","Паралельні транзакції виконуються так, ніби йдуть послідовно, і не бачать проміжних результатів одна одної","Після завершення транзакції всі обмеження цілісності даних, зовнішні ключі та типи лишаються в узгодженому стані"]},{"id":"o96","t":"net","q":"Яка послідовність прапорців передається при встановленні TCP-з'єднання?","a":["SYN -> SYN-ACK -> ACK","SYN -> ACK -> SYN-ACK","SYN -> SYN -> ACK","ACK -> SYN -> SYN-ACK"]},{"id":"o97","t":"net","q":"Як механізм Stack Canary виявляє спробу переповнення буфера на стеку?","a":["Розміщує контрольне значення перед адресою повернення (EIP/RIP) і перевіряє його цілісність перед return","Позначає сторінки стека як недоступні для виконання та генерує виняток при спробі передати на них керування","Випадково розміщує базу стека в адресному просторі щоразу при запуску, ускладнюючи вгадування адрес для шелл-коду","Копіює адресу повернення в окрему апаратну тіньову пам'ять та порівнює її при завершенні функції"]},{"id":"o98","t":"net","q":"У чому полягає суть принципу поліморфізму в об'єктно-орієнтованому програмуванні?","a":["Здатність об'єктів різних класів однаково реагувати на один і той самий виклик методу зі своєю специфічною реалізацією","Приховування внутрішнього стану об'єкта та надання доступу до нього лише через публічні методи інтерфейсу","Механізм створення нового класу на основі існуючого з успадкуванням його полів і методів та можливістю розширення","Виділення суттєвих характеристик об'єкта та ігнорування несуттєвих деталей для побудови спрощеної моделі предметної області"]},{"id":"o99","t":"net","q":"У чому різниця між User Mode (Ring 3) та Kernel Mode (Ring 0)?","a":["Ring 0 має прямий доступ до апаратного забезпечення, а Ring 3 ізольований і використовує системні виклики","Ring 3 має прямий доступ до апаратури та ядра, а Ring 0 призначений для застосунків користувача з обмеженими правами","Ring 0 виконує лише застосунки з графічним інтерфейсом, а Ring 3 — фонові служби та драйвери пристроїв","Різниця лише в пріоритеті планувальника: Ring 0 отримує більше процесорного часу, а права доступу до пам'яті однакові"]},{"id":"o100","t":"net","q":"На якому рівні моделі OSI працюють комутатори (switches) при комутації кадрів Ethernet?","a":["Канальний (L2 Data Link)","Мережевий (L3 Network)","Транспортний (L4 Transport)","Фізичний (L1 Physical)"]},{"id":"o101","t":"net","q":"Що робить механізм захисту ASLR (Address Space Layout Randomization)?","a":["Рандомізує базові адреси стеку, купи та бібліотек у пам'яті процесу","Забороняє виконання коду зі сторінок пам'яті, позначених як дані, на рівні апаратної підтримки процесора","Вставляє контрольне значення перед адресою повернення функції та перевіряє його цілісність","Шифрує вміст оперативної пам'яті процесу ключем, що змінюється при кожному запуску програми"]},{"id":"o102","t":"net","q":"Який механізм є обов'язковим у стандарті безпеки Wi-Fi мереж WPA3 для захисту від атак деавтентифікації (Deauthentication/Disassociation attacks)?","a":["Обов'язкове використання захисту керуючих кадрів PMF (Protected Management Frames, IEEE 802.11w)","Обов'язкове використання шифрування TKIP та автентифікації за MAC-адресами для всіх клієнтів мережі","Обов'язкове приховування SSID та вимкнення відповідей на зондувальні запити (Probe Request) для сторонніх клієнтів","Обов'язкове використання WPS із PIN-кодом для швидкого підключення пристроїв, що виключає ручне введення пароля"]},{"id":"o103","t":"netsec","q":"Що гарантує властивість Perfect Forward Secrecy (PFS) у сеансах зв'язку TLS?","a":["Компрометація довгострокового закритого ключа сервера в майбутньому не дозволить зловмиснику розшифрувати раніше перехоплений та збережений трафік","Сервер ніколи не зберігає сеансові ключі на диску й автоматично видаляє сертифікати після закінчення кожного сеансу зв'язку","Клієнт і сервер щоразу повторно автентифікують один одного сертифікатами X.509, що унеможливлює атаку «людина посередині»","Усі пакети отримують окремий лічильник і MAC, що виключає повторне відтворення перехопленого трафіку зловмисником"],"g":"g4"},{"id":"o104","t":"netsec","q":"Що є головним призначенням цифрового сертифіката X.509?","a":["Криптографічне зв'язування відкритого ключа з реальною особистістю чи доменом його власника за допомогою підпису центру сертифікації (CA)","Шифрування змісту повідомлень між клієнтом і сервером закритим ключем власника сертифіката, що виключає читання даних сторонніми","Зберігання паролів та облікових даних користувачів у захищеному вигляді на сервері автентифікації з обмеженим терміном дії записів","Захист вебсервера від DDoS-атак шляхом перевірки сертифіката клієнта перед встановленням з'єднання на рівні TCP"]},{"id":"o105","t":"netsec","q":"Чому режим лічильника з автентифікацією Галуа (Galois/Counter Mode — GCM) є рекомендованим у сучасних протоколах (TLS 1.3, IPsec)?","a":["Він забезпечує автентифіковане шифрування (AEAD), одночасно гарантуючи конфіденційність та цілісність даних з можливістю паралелізації обчислень","Він використовує асиметричні ключі для шифрування кожного блоку, що гарантує неможливість розшифрування без закритого ключа отримувача","Він не потребує унікального значення nonce, тому підходить для шифрування великих файлів на одному ключі без обмежень","Він створений для шифрування дисків, а не мережевого трафіку, і забезпечує тільки конфіденційність без перевірки цілісності даних"],"g":"g5"},{"id":"o106","t":"netsec","q":"Яку роль відіграє вектор ініціалізації (Initialization Vector — IV) у блокових шифрах (наприклад, CBC)?","a":["Забезпечує унікальність шифротексту при повторному шифруванні однакових відкритих текстів на одному й тому самому ключі","Збільшує довжину ключа шифрування до розміру блоку, що ускладнює повний перебір ключів у режимі атаки з відомим текстом","Підтверджує цілісність повідомлення, формуючи код автентичності, який додається до шифротексту та перевіряється одержувачем","Передає секретний ключ між відправником та одержувачем у зашифрованому вигляді за протоколом Діффі-Хеллмана"]},{"id":"o107","t":"netsec","q":"На якій математичній задачі базується криптографічна стійкість алгоритму RSA?","a":["Складність факторизації добутку двох великих простих чисел (n = p × q)","Складність обчислення дискретного логарифму в мультиплікативній групі скінченного поля великої розрядності","Складність розв'язання задачі про рюкзак для суперзростаючої послідовності чисел великого розміру","Складність знаходження найкоротшого вектора в багатовимірних ґратках великої розмірності"]},{"id":"o108","t":"netsec","q":"Чому режим ECB (Electronic Codebook) заборонено використовувати для шифрування великих файлів?","a":["Однакові блоки відкритого тексту шифруються в однакові блоки шифротексту, видаючи візуальні та структурні патерни даних","Режим ECB не забезпечує автентифікацію та дозволяє модифікацію шифротексту без виявлення, а шифрування кожного блоку є послідовним","Режим ECB має надто малий розмір блоку (32 біти), тому для великих файлів швидко вичерпується простір значень гамми","Режим ECB потребує вектора ініціалізації, який неможливо безпечно передавати для великих обсягів даних по відкритому каналу"]},{"id":"o109","t":"netsec","q":"Які математичні об'єкти використовуються в національному стандарті цифрового підпису України ДСТУ 4145-2002?","a":["Еліптичні криві над двійковими полями GF(2^m)","Еліптичні криві над простими полями GF(p) з параметрами NIST P-256","Мультиплікативна група скінченного простого поля та задача дискретного логарифму","Кільце цілих чисел за складеним модулем n = p × q та задача факторизації"]},{"id":"o110","t":"netsec","q":"Яку конструкцію та розмір вихідного дайджесту має український національний стандарт гешування ДСТУ 7564:2014 «Купина»?","a":["Конструкцію губки (Sponge function), довжина гешу 256, 384 або 512 біт","Конструкцію Меркла-Дамгора з 32-розрядними словами, довжина гешу лише 160 біт","Конструкцію Файстеля з 16 раундами, довжина гешу 128 або 192 біти","Конструкцію HMAC на основі блокового шифру, довжина гешу 64 біти"]},{"id":"o111","t":"netsec","q":"У чому перевага протоколу OCSP (Online Certificate Status Protocol) над списками відкликання CRL?","a":["OCSP дозволяє перевірити статус конкретного сертифіката в режимі онлайн без необхідності завантажувати великі списки відкликаних сертифікатів CRL","OCSP шифрує сертифікати з використанням відкритого ключа центру сертифікації, що унеможливлює їх підробку та підміну в мережі","OCSP зберігає закриті ключі користувачів у захищеному сховищі центру сертифікації та автоматично відкликає їх після закінчення терміну","OCSP забезпечує автентифікацію клієнтів у мережі за допомогою Kerberos та перевіряє їхні квитки без звернення до контролера домену"]},{"id":"o112","t":"netsec","q":"Які класичні криптографічні алгоритми опиняться під прямою загрозою зламу в разі появи потужного квантового комп'ютера через алгоритм Шора?","a":["Асиметричні криптосистеми на основі факторизації та дискретного логарифму (RSA, DSA, Diffie-Hellman, ECDSA, ДСТУ 4145)","Симетричні блокові шифри та геш-функції (AES-256, SHA-3, ДСТУ 7624 «Калина», ДСТУ 7564 «Купина») за будь-якої довжини ключа","Усі криптосистеми без винятку, оскільки квантовий комп'ютер миттєво здійснює перебір будь-якого простору ключів незалежно від його розміру","Лише потокові шифри та генератори псевдовипадкових чисел (RC4, ChaCha20), тоді як блокові шифри й асиметричні системи залишаються стійкими"]},{"id":"o113","t":"netsec","q":"Яка основна мета протоколу обміну ключами Діффі-Хеллмана (Diffie-Hellman)?","a":["Безпечне узгодження спільного секретного ключа між двома сторонами через відкритий незахищений канал зв'язку","Створення цифрового підпису документа та перевірка його автентичності будь-якою стороною за допомогою відкритого ключа підписувача","Шифрування великих обсягів даних за допомогою пари асиметричних ключів з вищою швидкістю порівняно з симетричними шифрами","Автентифікація сторін за допомогою сертифікатів без обміну ключовим матеріалом і без створення сеансового ключа"]},{"id":"o114","t":"netsec","q":"Яка вразливість середовища Active Directory використовується зловмисником під час проведення атаки Kerberoasting?","a":["Можливість будь-якого автентифікованого користувача домену запросити квиток TGS для облікового запису сервісу (SPN) та офлайн підібрати пароль за гешем","Можливість анонімного користувача перехопити квиток TGT у мережі та використати його повторно для входу від імені адміністратора домену","Підробка квитків TGT за допомогою хешу облікового запису krbtgt, що дозволяє необмежений час діяти від імені будь-якого користувача","Передача хешу NTLM користувача іншим службам без знання пароля (Pass-the-Hash) для бокового переміщення між серверами мережі"]},{"id":"o115","t":"netsec","q":"Яку довжину блоку підтримує національний симетричний блоковий шифр України ДСТУ 7624:2014 «Калина»?","a":["128, 256 або 512 біт","64, 128 або 192 біти","128, 192 або 256 біт","256, 512 або 1024 біти"]},{"id":"o116","t":"netsec","q":"Що стверджує парадокс днів народження (Birthday Paradox) щодо складності знаходження колізії для n-бітної геш-функції?","a":["Колізію можна знайти за 2^(n/2) операцій, що вдвічі менше за повний перебір першообразу 2^n","Колізію можна знайти за 2^(n−1) операцій, що вдвічі менше за повний перебір усіх можливих значень гешу","Колізію неможливо знайти швидше, ніж за 2^n операцій, оскільки геш-функція є односторонньою та необоротною","Колізію можна знайти за n² операцій, що значно менше за перебір, тому розмір гешу має бути не менше 1024 біт"]},{"id":"o117","t":"netsec","q":"Для чого призначений алгоритм HMAC (Hash-based Message Authentication Code)?","a":["Для одночасної перевірки цілісності та справжності (автентичності) повідомлення за допомогою секретного симетричного ключа та геш-функції","Для шифрування повідомлення симетричним ключем із наступним обчисленням геш-функції від шифротексту без забезпечення автентичності відправника","Для підписання повідомлення закритим ключем відправника, щоб будь-яка сторона могла перевірити підпис відкритим ключем без спільного секрету","Для генерації ключів із паролів користувача за допомогою багаторазового гешування з сіллю та великою кількістю ітерацій"]},{"id":"o118","t":"netsec","q":"Які операції виконуються під час створення електронного підпису документу відправником?","a":["Обчислюється геш-образ документу, який потім шифрується (підписується) особистим (закритим) ключем автора","Документ шифрується відкритим ключем одержувача, а отримане значення додається до повідомлення як підпис автора","Обчислюється геш-образ документу, який шифрується відкритим ключем автора, щоб одержувач міг розшифрувати його закритим","Документ шифрується симетричним сеансовим ключем, а сам ключ передається одержувачу разом із сертифікатом відправника"]},{"id":"o119","t":"netsec","q":"Який розмір блоку використовує розповсюджений симетричний блоковий шифр AES (Rijndael)?","a":["128 біт","64 біти","256 біт","192 біти"]},{"id":"o120","t":"os","q":"Яка дія є першочерговою на етапі «Стримування» (Containment) при виявленні активно поширюваного вірусу-вимагача (Ransomware) на робочій станції в локальній мережі?","a":["Негайна ізоляція зараженого комп'ютера від мережі (відключення Ethernet-кабелю або Wi-Fi/мережева ізоляція через EDR)","Негайне вимкнення живлення комп'ютера кнопкою та розбирання корпусу для вилучення жорсткого диска з метою його подальшого аналізу","Сплата викупу зловмисникам за ключ розшифрування та подальше відновлення файлів без залучення служби реагування на інциденти","Повне форматування диска зараженої станції та перевстановлення операційної системи з резервної копії без збереження доказів"]},{"id":"o121","t":"os","q":"Яка ключова перевага систем класу EDR (Endpoint Detection and Response) порівняно з класичними антивірусами сигнатурного типу?","a":["Безперервний моніторинг поведінки процесів, фіксація ланцюжків виконання (Process Lineage) та можливість ізоляції хоста і розслідування інцидентів","Використання виключно хмарної бази сигнатур відомих загроз, що оновлюється щогодини, і автоматичне видалення всіх файлів, не внесених до білого списку","Централізоване керування патчами та автоматичне встановлення оновлень безпеки на всіх вузлах без аналізу поведінки процесів","Шифрування файлів користувача та блокування зовнішніх носіїв у режимі «за замовчуванням» без можливості розслідування інцидентів"]},{"id":"o122","t":"swsec","q":"Яка різниця між «Тактикою» (Tactic) та «Технікою» (Technique) у фреймворку MITRE ATT&CK?","a":["Тактика відповідає на запитання «Чого намагається досягти атакуючий?» (мета), а техніка — «Як саме він це реалізує?» (спосіб)","Тактика — це конкретний інструмент або шкідлива програма, а техніка — загальна назва групи зловмисників, що її використовує","Тактика описує захисні заходи, що застосовує команда SOC, а техніка — спосіб, у який зловмисник їх обходить","Тактика визначає ціль атаки за галуззю економіки, а техніка — країну походження атакуючої групи та її ресурси"]},{"id":"o123","t":"swsec","q":"Що в контексті роботи системи управління подіями інформаційної безпеки (SIEM) називається «нормалізацією подій» (Event Normalization)?","a":["Перетворення різнорідних форматів журналів (Syslog, Windows Event Log, Firewall logs) до єдиної стандартизованої схеми полів (IP, користувач, дія)","Видалення дублікатів та шуму з журналів на джерелах подій, щоб скоротити обсяг даних і зменшити витрати на їх зберігання","Зіставлення подій із базою відомих індикаторів компрометації та присвоєння їм рівня критичності для подальшого пріоритезування","Об'єднання кількох пов'язаних подій в один інцидент за правилами кореляції та автоматичне створення заявки для аналітика SOC"]},{"id":"o124","t":"inc","q":"Яке з наведених налаштувань є найкращою практикою безпеки при запуску Docker-контейнера у виробничому середовищі?","a":["Використання непривілейованого користувача (non-root), обмеження capabilities (--cap-drop=ALL) та прапорець --read-only","Запуск із прапорцем --privileged для повного доступу до пристроїв хоста та монтування сокета Docker усередину контейнера","Запуск від root для сумісності та використання режиму --network=host, щоб контейнер мав доступ до всіх мережевих інтерфейсів","Збереження паролів і токенів у змінних середовища всередині образу та використання тегу latest для всіх образів"]},{"id":"o125","t":"inc","q":"Який офіційний підсумковий документ реєструє Держспецзв'язку за результатами державної експертизи КСЗІ?","a":["Атестат відповідності КСЗІ","Сертифікат відповідності КСЗІ","Ліцензія на здійснення діяльності у сфері ТЗІ","Експертний висновок про готовність системи"],"g":"g12"},{"id":"o126","t":"inc","q":"Згідно з НД ТЗІ 1.4-001-2000, яка автоматизована система (АС) належить до класу 1?","a":["Одномашинний однокористувацький комплекс, який обробляє інформацію однієї або різних категорій конфіденційності","Локальна багатомашинна багатокористувацька система, що обробляє інформацію однієї категорії конфіденційності","Розподілена автоматизована система з багатьох вузлів, об'єднаних каналами зв'язку, що обробляє різні категорії інформації","Одномашинний багатокористувацький комплекс, у якому всі користувачі мають однакові повноваження до інформації"]},{"id":"o127","t":"inc","q":"Відповідно до НД ТЗІ 2.5-004-99, який критерій позначає послуги забезпечення конфіденційності?","a":["Критерій К (КД — дискреційний, КМ — мандатний захист)","Критерій Ц (ЦД — дискреційний, ЦМ — мандатний захист)","Критерій Д (ДВ — відновлення, ДР — резервування ресурсів)","Критерій Н (НР — реєстрація, НИ — ідентифікація та автентифікація)"]},{"id":"o128","t":"inc","q":"Який нормативний документ визначає порядок розроблення Технічного завдання на створення КСЗІ?","a":["НД ТЗІ 3.7-003-2005 (Порядок розроблення ТЗ)","НД ТЗІ 1.1-002-99 (Загальні положення щодо захисту інформації в комп'ютерних системах від НСД)","НД ТЗІ 2.5-004-99 (Критерії оцінки захищеності інформації в комп'ютерних системах від НСД)","ДСТУ 3396.0-96 (Технічний захист інформації. Основні положення)"]},{"id":"o129","t":"inc","q":"Що таке дискреційне розмежування доступу (DAC) у комп'ютерних системах?","a":["Керування доступом, за якого власник ресурсу самостійно визначає права інших користувачів (Read, Write, Execute)","Керування доступом, за якого права визначаються рівнем допуску суб'єкта та грифом секретності об'єкта, а власник їх змінити не може","Керування доступом на основі ролей, у яких об'єднані набори прав, що призначаються користувачам відповідно до їхніх посад","Керування доступом за атрибутами суб'єкта, об'єкта та середовища (час, місце), що обчислюються політикою в момент запиту"]},{"id":"o130","t":"inc","q":"У чому полягає принципова відмінність між механізмами ядра Linux Namespaces та Control Groups (cgroups)?","a":["Namespaces ізолюють видимість системних ресурсів (PID, мережа, IPC), а cgroups обмежують та обліковують обсяг використання ресурсів (CPU, RAM, I/O)","Namespaces обмежують обсяг використання процесора та пам'яті, а cgroups ізолюють видимість процесів, мережевих інтерфейсів і файлових систем","Namespaces відповідають за шифрування файлових систем контейнерів, а cgroups — за автентифікацію процесів і розмежування облікових записів","Namespaces фільтрують системні виклики процесів за білим списком, а cgroups відокремлюють привілеї root від привілеїв звичайних користувачів"],"g":"g13"},{"id":"o131","t":"inc","q":"На захист якої складової інформаційної безпеки орієнтована модель Біба (Biba Model)?","a":["На цілісність інформації (правило No Write Up, No Read Down)","На конфіденційність інформації (правило No Read Up, No Write Down)","На доступність інформації (правило No Delete Up, No Lock Down)","На розмежування обов'язків (правило «Китайської стіни» та конфлікт інтересів)"]},{"id":"o132","t":"inc","q":"Яка послуга за критерієм «Ц» НД ТЗІ 2.5-004-99 забезпечує виявлення фактів несанкціонованої модифікації інформації?","a":["Послуга ЦВ (виявлення несанкціонованої модифікації)","Послуга КД (дискреційна конфіденційність)","Послуга ДР (резервування ресурсів)","Послуга НР (реєстрація подій)"]},{"id":"o133","t":"inc","q":"Який термін дії встановлюється для Атестата відповідності КСЗІ за загальним правилом?","a":["До 5 років (за умови незмінності умов функціонування та конфігурації системи)","До 1 року (з обов'язковим щорічним повторним проходженням експертизи)","До 10 років (за умови щорічного проведення внутрішнього аудиту безпеки)","Безстроково (за умови відсутності зареєстрованих інцидентів ІБ)"]},{"id":"o134","t":"inc","q":"Яке правило моделі Белла-ЛаПадула описує принцип «No Read Up»?","a":["Суб'єкт з нижчим допуском не може читати об'єкт з вищим рівнем секретності","Суб'єкт з вищим допуском не може записувати інформацію в об'єкт з нижчим рівнем секретності","Суб'єкт не може змінювати рівень секретності об'єкта, якщо він не є його власником у системі","Суб'єкт з вищим допуском не може читати об'єкт з нижчим рівнем цілісності без дозволу адміністратора"]},{"id":"o135","t":"inc","q":"Хто має право проводити експертні випробування КСЗІ в Україні?","a":["Організація, яка має ліцензію Адміністрації Держспецзв'язку на проведення робіт у сфері ТЗІ та внесена до реєстру організаторів експертизи","Будь-яка організація-розробник системи, яка самостійно проводить випробування власного продукту та складає висновок про його відповідність","Підрозділ Служби безпеки України, що має допуск до державної таємниці та акредитацію Національного агентства з акредитації України","Лише Адміністрація Держспецзв'язку своїми підрозділами; залучення сторонніх організацій до експертизи законодавством не допускається"]},{"id":"o136","t":"risk","q":"Яку нову (шосту) базову функцію було додано до структури NIST Cybersecurity Framework у версії CSF 2.0 (2024 рік)?","a":["GOVERN (Керування / Врядування)","PLAN (Планування)","MANAGE (Менеджмент / Управління ризиками)","AUDIT (Аудит / Перевірка)"],"g":"g8"},{"id":"o137","t":"risk","q":"Яке обов'язкове призначення має документ «Заява про застосовність» (Statement of Applicability, SoA) згідно з вимогами стандарту ISO/IEC 27001?","a":["Документування вибору заходів безпеки з Annex A, обґрунтування їх включення або виключення, та статус їх впровадження в СУІБ","Опис меж та сфери застосування СУІБ із переліком підрозділів, процесів, місць розташування й інтерфейсів із зовнішніми сторонами","Перелік ідентифікованих ризиків із оцінками ймовірності та впливу, власниками ризиків та затвердженим планом їх обробки","Декларація вищого керівництва про зобов'язання щодо безпеки інформації, що визначає цілі та загальні принципи роботи організації"]},{"id":"o138","t":"risk","q":"У чому полягає різниця між метриками RTO (Recovery Time Objective) та RPO (Recovery Point Objective) у плануванні відновлення після аварій (DRP)?","a":["RTO — це максимально допустимий час простою сервісу до відновлення, а RPO — максимально допустимий обсяг втрачених даних у часовому вимірі (від останнього бекапу)","RTO — це максимально допустимий обсяг втрачених даних, а RPO — максимально допустимий час простою сервісу до відновлення після аварії","RTO визначає час між двома послідовними резервними копіями, а RPO — час, потрібний для перемикання користувачів на резервний майданчик","RTO — це середній час напрацювання між відмовами обладнання, а RPO — середній час ремонту несправного компонента після збою"]},{"id":"o139","t":"risk","q":"На які чотири категорії (домени) розділено заходи безпеки в оновленому додатку Annex A стандарту ISO/IEC 27001:2022?","a":["Організаційні (Organizational), кадрові/людські (People), фізичні (Physical) та технологічні (Technological)","Технічні (Technical), Адміністративні (Administrative), Фізичні (Physical), Правові (Legal)","Запобіжні (Preventive), Виявляючі (Detective), Коригувальні (Corrective), Відновлювальні (Recovery)","Управління (Governance), Ризики (Risk), Відповідність (Compliance), Аудит (Audit)"],"g":"g9"},{"id":"o140","t":"risk","q":"Як відповідно до стандартів аудиту систем управління (ISO 19011) класифікується аудит, що проводиться незалежним акредитованим органом сертифікації для видачі сертифіката відповідності?","a":["Аудит третьої сторони (Third-party audit / сертифікаційний аудит)","Аудит першої сторони (внутрішній аудит, що виконується силами самої організації)","Аудит другої сторони (аудит замовником або партнером, що перевіряє свого постачальника)","Наглядовий аудит регулятора (інспекційна перевірка державним органом нагляду)"]},{"id":"o141","t":"risk","q":"Згідно з міжнародною методологією управління ризиками інформаційної безпеки (ISO/IEC 27005 / NIST SP 800-30), рівень кіберризику визначається як комбінація:","a":["Ймовірності (правдоподібності) реалізації загрози через наявну вразливість та ступеня негативних наслідків (впливу на активи)","Вартості активу та кількості встановлених засобів захисту, помноженої на відсоток уже виявлених інцидентів за попередній період","Кількості виявлених вразливостей та кількості працівників, що мають доступ до системи, поділених на бюджет, виділений на безпеку","Рівня зрілості процесів безпеки за моделлю CMMI та відсотка відповідності вимогам стандарту за результатами сертифікаційного аудиту"]},{"id":"o142","t":"law","q":"Яке ключове посилення вимог внесено директивою ЄС NIS2?","a":["Вимоги до безпеки ланцюгів постачання та персональна відповідальність керівництва","Заборона використання обладнання з третіх країн та обов'язкове зберігання всіх даних виключно на серверах у межах ЄС","Обов'язкове шифрування всього інтернет-трафіку громадян та передача ключів національним регуляторам на вимогу","Скасування вимог щодо повідомлення про інциденти для малих підприємств і заміна їх добровільною самооцінкою"]},{"id":"o143","t":"law","q":"Коли створення КСЗІ з підтвердженою відповідністю є обов'язковим за законодавством України?","a":["При обробці державних ресурсів або інформації з обмеженим доступом за законом","Для всіх приватних компаній, що мають вебсайт та обробляють персональні дані клієнтів у будь-яких обсягах","Лише для банків та фінансових установ, що мають ліцензію Національного банку України на здійснення діяльності","Тільки за рішенням суду після виявлення факту витоку інформації, що містить державну таємницю"]},{"id":"o144","t":"law","q":"Який державний орган згідно із ЗУ «Про основні засади забезпечення кібербезпеки України» формує та реалізує політику у сфері кіберзахисту державних інформаційних ресурсів?","a":["Державна служба спеціального зв’язку та захисту інформації України (ДССЗЗІ)","Служба безпеки України (СБУ) спільно з Генеральним штабом ЗСУ","Міністерство цифрової трансформації України (Мінцифри)","Національний банк України та Національна комісія з цінних паперів"]},{"id":"o145","t":"law","q":"Що в стандарті ISO/IEC 15408 є незалежним від реалізації набором вимог безпеки для певної категорії продуктів?","a":["Protection Profile (PP)","Security Target (ST)","Target of Evaluation (TOE)","Evaluation Assurance Level (EAL)"]},{"id":"o146","t":"law","q":"На які дві категорії за порядком доступу поділяється інформація за ЗУ «Про інформацію»?","a":["Відкрита інформація та інформація з обмеженим доступом","Державна таємниця та комерційна таємниця","Службова інформація та персональні дані","Публічна інформація та конфіденційна інформація"]},{"id":"o147","t":"law","q":"Протягом якого часу власник або оператор об'єкта критичної інфраструктури зобов'язаний повідомити урядову команду CERT-UA про виявлення критичного кіберінциденту?","a":["Невідкладно, але не пізніше встановленого нормативного строку (протягом перших годин)","Протягом 30 діб після завершення внутрішнього розслідування та усунення наслідків інциденту","Протягом 7 робочих днів із моменту виявлення, після погодження звіту з керівником","Щоквартально разом зі звітом про стан захищеності інформаційних систем"]},{"id":"o148","t":"law","q":"Яка обов'язкова вимога встановлена Законом України «Про захист інформації в інформаційно-комунікаційних системах» щодо державних інформаційних ресурсів при їх обробці в ІКС?","a":["Створення комплексної системи захисту інформації (КСЗІ) з підтвердженою відповідністю","Обов'язкове розміщення серверів лише в приміщеннях Держспецзв'язку та підключення їх до державної мережі","Шифрування всіх даних іноземними алгоритмами, що пройшли міжнародну сертифікацію (FIPS 140-3)","Щорічна сплата збору до державного бюджету та реєстрація кожної системи в Єдиному реєстрі ІКС"]},{"id":"o149","t":"law","q":"Який міжнародний договір став основою криміналізації кіберзлочинів в Україні?","a":["Будапештська конвенція про кіберзлочинність (ETS 185)","Стамбульська конвенція про запобігання насильству (CETS 210)","Конвенція про захист осіб у зв'язку з автоматизованою обробкою персональних даних (ETS 108)","Конвенція ООН проти транснаціональної організованої злочинності (Палермська, 2000)"]},{"id":"o150","t":"law","q":"До якої категорії критичності згідно із Законом України «Про критичну інфраструктуру» належать об'єкти, порушення функціонування яких призводить до наслідків національного (загальнодержавного) рівня?","a":["I категорія критичності (особливо важливі об'єкти держави)","II категорія критичності (важливі об'єкти регіонального рівня)","III категорія критичності (об'єкти місцевого значення)","IV категорія критичності (об'єкти підвищеної уваги)"]},{"id":"o151","t":"law","q":"Яке ключове завдання покладено на Службу безпеки України (СБУ) у національній системі кібербезпеки відповідно до чинного законодавства?","a":["Попередження, виявлення та припинення кібертероризму та кібершпигунства проти безпеки держави","Видача кваліфікованих сертифікатів відкритих ключів та акредитація центрів сертифікації ключів на території країни","Державний нагляд за дотриманням законодавства про захист персональних даних і розгляд скарг громадян на його порушення","Забезпечення функціонування національної телекомунікаційної мережі та технічний захист державних інформаційних ресурсів"]},{"id":"o152","t":"law","q":"До якої категорії згідно із ЗУ «Про захист персональних даних» належать дані про біометричні та генетичні характеристики особи, її здоров'я та політичні погляди?","a":["Особливі категорії персональних даних (чутливі дані)","Загальні категорії персональних даних (ідентифікаційні дані)","Відкриті персональні дані (загальнодоступні відомості)","Службові персональні дані (кадрова інформація)"]},{"id":"o153","t":"law","q":"Який максимальний термін повідомлення наглядового органу про витік персональних даних за GDPR?","a":["Не пізніше 72 годин","Не пізніше 24 годин","Не пізніше 7 діб","Не пізніше 30 діб"]},{"id":"o154","t":"law","q":"У складі якого відомства функціонує CERT-UA?","a":["ДССЗЗІ України","СБУ України","Національний банк України","Міністерство цифрової трансформації України"]},{"id":"o155","t":"law","q":"Які ступені секретності державної таємниці встановлені в Україні?","a":["Особливої важливості, Цілком таємно, Таємно","Цілком таємно, Таємно, Для службового користування","Особливої важливості, Таємно, Конфіденційно","Цілком таємно, Таємно, Обмеженого доступу"]},{"id":"o156","t":"law","q":"Який обов'язковий організаційний захід повинен реалізувати власник об'єкта критичної інфраструктури згідно з Постановою КМУ №518?","a":["Створення служби кіберзахисту або залучення підрядника та розробка плану реагування","Щорічне проведення публічних навчань для населення та оприлюднення звітів про всі виявлені вразливості на сайті","Передача керування об'єктом військовій адміністрації на період дії воєнного стану та припинення підключення до Інтернету","Заміна всього обладнання на продукцію вітчизняного виробництва протягом одного року від набрання чинності постановою"]},{"id":"o157","t":"law","q":"Що є головною юридичною відмінністю КЕП від інших електронних підписів?","a":["Створюється за допомогою захищеного КЗЕП та базується на кваліфікованому сертифікаті","Не потребує сертифіката відкритого ключа, оскільки створюється довірчою стороною за допомогою симетричного ключа","Має юридичну силу лише за наявності штампу чи печатки організації та підпису свідка або нотаріуса","Створюється лише у хмарних сервісах іноземних провайдерів та визнається виключно в межах ЄС за регламентом eIDAS"],"g":"g14"},{"id":"o158","t":"law","q":"Що відповідно до Закону України «Про основні засади забезпечення кібербезпеки України» розуміється під терміном «кібероборона»?","a":["Сукупність політичних, економічних, військових та технічних заходів для відсічі збройній агресії у кіберпросторі","Комплекс правових, організаційних та технічних заходів, спрямованих на захист державних електронних інформаційних ресурсів від кібератак","Діяльність спецслужб, спрямована на виявлення, попередження та припинення кіберзлочинності, кібертероризму і шпигунства в кіберпросторі","Здатність системи протистояти кібератакам, зберігаючи працездатність та швидко відновлюючись після кіберінцидентів без втрат даних"]},{"id":"o159","t":"law","q":"Згідно із Законом України «Про хмарні послуги», де забороняється розміщувати центри обробки даних (ЦОД) надавачам хмарних послуг для органів державної влади України?","a":["На території держав, визнаних Верховною Радою України державами-агресорами (державами-окупантами)","На території будь-яких держав, що не є членами Європейського Союзу та НАТО, незалежно від рівня безпеки","На території держав, що не ратифікували Будапештську конвенцію про кіберзлочинність, незалежно від їх відносин з Україною","За межами України взагалі: усі ЦОД для держорганів мають розташовуватися виключно на території України без винятків"]},{"id":"o160","t":"law","q":"Який цикл управління безперервним покращенням є основою стандарту ISO/IEC 27001?","a":["PDCA (Plan — Do — Check — Act)","OODA (Observe — Orient — Decide — Act)","DMAIC (Define — Measure — Analyze — Improve — Control)","IDEAL (Initiating — Diagnosing — Establishing — Acting — Learning)"]},{"id":"o161","t":"law","q":"Яка головна функція покладена на ENISA Регламентом ЄС 2019/881?","a":["Розробка європейських схем сертифікації кібербезпеки продуктів ІКТ","Оперативне реагування на кібератаки в державах-членах ЄС та проведення розслідувань кіберзлочинів разом із Європолом","Нагляд за дотриманням вимог GDPR та накладення штрафів на компанії за порушення при обробці персональних даних","Розроблення та розгортання єдиного європейського хмарного сховища для державних установ усіх держав-членів"]},{"id":"n1","t":"tzi","q":"Який прилад призначений для виявлення працюючих радіозакладок за їхнім власним випромінюванням у радіодіапазоні?","a":["Індикатор електромагнітного поля (радіочастотомір, сканерний радіоприймач)","Нелінійний локатор, що реєструє гармоніки відбитого зондувального сигналу від p-n переходів","Металодетектор, що реагує на зміну індуктивності котушки поблизу металевих корпусів","Віброакустичний генератор, що створює маскувальний шум на стінах приміщення"]},{"id":"n2","t":"tzi","q":"Що розуміють під акустичним каналом витоку мовної інформації?","a":["Розповсюдження звукових хвиль у повітрі та їх перехоплення мікрофонами, у тому числі направленими чи прихованими","Розповсюдження коливань виключно у твердих тілах (стінах, трубах) та їх перехоплення електронним стетоскопом","Випромінювання електромагнітних хвиль під час роботи комп'ютера та їх прийом спеціальними антенами","Передавання інформації по проводах телефонної мережі та її перехоплення паралельним підключенням апарата"]},{"id":"n3","t":"tzi","q":"У чому полягає суть віброакустичного каналу витоку інформації?","a":["Мовні коливання збуджують вібрації будівельних конструкцій і комунікацій, які знімаються контактними датчиками (стетоскопами)","Звук голосу перетворюється на електричний сигнал елементами допоміжних технічних засобів, що мають мікрофонний ефект","Зловмисник реєструє зміни інтенсивності відбитого лазерного променя від скла без фізичного контакту з вікном","Інформативний сигнал модулює струм у мережі живлення та передається по проводах за межі контрольованої зони"]},{"id":"n4","t":"tzi","q":"Що таке коефіцієнт екранування (ефективність екранування) електромагнітного екрана?","a":["Відношення напруженості поля без екрана до напруженості поля за наявності екрана, яке виражають у децибелах (дБ)","Відношення кількості металу в оболонці екрана до площі екранованого приміщення, що виражається у відсотках","Максимальна відстань від екрана, на якій ще можна перехопити сигнал від обладнання, розміщеного всередині","Різниця потенціалів між екраном та землею, що вимірюється вольтметром під час перевірки заземлення"]},{"id":"n5","t":"tzi","q":"Що в сфері ТЗІ означає термін «допоміжні технічні засоби і системи» (ДТЗС)?","a":["Технічні засоби, що не призначені для обробки інформації, але розміщені в приміщеннях (телефони, сигналізація, годинники, гучномовці)","Основне обладнання, яке безпосередньо обробляє та передає інформацію з обмеженим доступом: комп'ютери, АТС, принтери","Резервні пристрої живлення та охолодження, що забезпечують безперервну роботу серверів у разі аварії мережі","Спеціальні засоби захисту від витоку інформації, такі як генератори шуму, фільтри, екрани та пристрої ВЧ-розв'язки, що встановлюються на об'єкті"]},{"id":"n6","t":"tzi","q":"Що в сфері ТЗІ означає термін «основні технічні засоби» (ОТЗ)?","a":["Технічні засоби, що безпосередньо обробляють, зберігають або передають інформацію з обмеженим доступом","Усі технічні засоби на об'єкті, які споживають електроенергію або підключені до мережі живлення будівлі","Засоби захисту інформації, які встановлюються на об'єкті для протидії витоку технічними каналами","Прилади, якими користуються спеціалісти під час проведення спеціальних досліджень та пошуку закладок"]},{"id":"n7","t":"tzi","q":"Що означає абревіатура (кодова назва) TEMPEST у галузі захисту інформації?","a":["Комплекс досліджень і технологій захисту від витоку інформації через побічні електромагнітні випромінювання й наводки","Американський стандарт шифрування мовного трафіку в телефонних лініях спеціального зв'язку та системах урядового зв'язку США","Метод дистанційного відключення радіозакладок за допомогою потужного електромагнітного імпульсу","Систему сигналізації та контролю доступу до режимних приміщень, що використовується у військових об'єктах"]},{"id":"n8","t":"tzi","q":"Яка основна роль заземлення в системі технічного захисту інформації?","a":["Відведення паразитних струмів і забезпечення ефективності екранів та фільтрів, що знижує рівень ПЕМІН","Створення маскувального шуму в ланцюгах живлення, який заважає перехопленню інформативних сигналів","Збільшення відстані між технічним засобом та контрольованою зоною шляхом заглиблення кабелів у ґрунт","Перетворення акустичних сигналів на електричні для подальшого аналізу їх рівня у приміщенні"]},{"id":"n9","t":"tzi","q":"Чому волоконно-оптичні лінії зв'язку вважаються більш захищеними від витоку інформації за ПЕМІН?","a":["Вони не випромінюють електромагнітного поля та не чутливі до наводок, тому дистанційне перехоплення через ПЕМІН практично неможливе","Вони використовують виключно шифровані протоколи на фізичному рівні, що унеможливлює читання даних навіть після підключення до волокна","Світловий сигнал миттєво вимикається при будь-якому механічному впливі на кабель, тому підключення без розриву лінії є неможливим","Вони мають вбудоване металеве екранування з багатошаровою фольгою, яка забезпечує ефективність понад 120 дБ"]},{"id":"n10","t":"tzi","q":"Який із наведених заходів належить до пасивних заходів захисту мовної інформації у виділеному приміщенні?","a":["Звукоізоляція: подвійні двері, тамбури, звукопоглинальні матеріали та ущільнення вікон","Генерація маскувального акустичного шуму просторовими та віброакустичними генераторами","Пошук закладних пристроїв нелінійними локаторами та індикаторами поля","Встановлення пристроїв подавлення диктофонів, що створюють потужне електромагнітне поле"]},{"id":"n11","t":"tzi","q":"Що таке виділене приміщення (ВП) у контексті захисту інформації?","a":["Приміщення, призначене для проведення переговорів та нарад з обговорення інформації з обмеженим доступом, до якого висуваються підвищені вимоги щодо захисту","Приміщення в серверній частині будівлі, де розміщено обладнання, що обробляє електронну інформацію, та де заборонено перебування сторонніх осіб","Будь-який кабінет організації, у якому є сейф для зберігання документів із грифом обмеження доступу","Окрема будівля на території підприємства, що охороняється спеціальним підрозділом та знаходиться в контрольованій зоні"]},{"id":"n12","t":"tzi","q":"Для чого використовують виявлювачі (детектори) диктофонів?","a":["Для виявлення працюючих диктофонів за магнітним полем двигуна чи ВЧ-підмагнічуванням та вимикання їх потужним полем","Для маскування мови в приміщенні шляхом генерації мовоподібних завад у діапазоні 250–4000 Гц","Для визначення місцезнаходження радіозакладок за рівнем потужності їхнього випромінювання на різних частотах","Для вимірювання рівнів ПЕМІН від комп'ютерів та визначення розміру зони R2 під час спецдосліджень"]},{"id":"n13","t":"tzi","q":"Для чого призначені мережеві фільтри та лінійні ВЧ-розв'язки в телефонних і силових лініях виділеного приміщення?","a":["Для запобігання виходу інформативних сигналів та наводок за межі приміщення по лініях, що виходять у неконтрольовану зону","Для підвищення потужності сигналу в лініях зв'язку та компенсації втрат на великих відстанях між абонентами","Для автоматичного шифрування телефонних розмов за допомогою вбудованих криптографічних модулів","Для виявлення підключення сторонніх пристроїв за зміною опору лінії та автоматичного подавання сигналу тривоги"]},{"id":"n14","t":"crypto","q":"У чому принципова відмінність симетричного шифрування від асиметричного?","a":["У симетричному для шифрування і розшифрування використовується один спільний секретний ключ, в асиметричному — пара: відкритий та закритий ключі","У симетричному використовується пара ключів, а в асиметричному — один ключ, який передається відкритим каналом всім учасникам","Симетричне шифрування застосовується лише для цифрового підпису, а асиметричне — лише для шифрування великих обсягів даних за допомогою єдиного відкритого ключа","Симетричні алгоритми працюють тільки з текстом, а асиметричні — тільки з бінарними файлами та зображеннями, і не можуть застосовуватися в мережевих протоколах"]},{"id":"n15","t":"crypto","q":"Який режим роботи блокового шифру перетворює його на потоковий і дозволяє паралельне шифрування блоків?","a":["CTR (Counter Mode, режим лічильника)","ECB (Electronic Codebook, режим електронної кодової книги) без вектора ініціалізації","CBC (Cipher Block Chaining, режим зчеплення блоків шифротексту)","CMAC (Cipher-based MAC, код автентичності на основі шифру)"]},{"id":"n16","t":"crypto","q":"Для чого під час зберігання паролів до них додається «сіль» (salt)?","a":["Щоб однакові паролі давали різні геш-значення та щоб унеможливити використання заздалегідь обчислених райдужних таблиць","Щоб збільшити довжину пароля до необхідного мінімуму і гарантувати стійкість до атак повного перебору при будь-якій складності","Щоб шифрувати пароль симетричним ключем, який зберігається в окремому захищеному сховищі на сервері","Щоб прискорити перевірку пароля при вході, зменшивши кількість обчислень геш-функції на стороні сервера"]},{"id":"n17","t":"crypto","q":"Яка функція найбільше підходить для безпечного зберігання паролів користувачів?","a":["Argon2 / bcrypt / scrypt — повільні адаптивні функції зі сіллю","SHA-256 без солі, оскільки вона швидка та має великий розмір дайджесту","MD5 з багаторазовим повторенням 10 разів, оскільки вона широко підтримується в бібліотеках","AES-128 у режимі ECB з ключем, що зберігається разом із базою даних користувачів"]},{"id":"n18","t":"crypto","q":"Які умови необхідні для абсолютної стійкості шифру з одноразовим блокнотом (One-Time Pad)?","a":["Ключ випадковий, не коротший за повідомлення, зберігається в таємниці та використовується лише один раз","Ключ має довжину щонайменше 256 біт, генерується псевдовипадковим генератором і змінюється раз на добу","Ключ є хешем від пароля користувача, а повідомлення розбивається на блоки по 128 біт із додаванням сіллю","Ключ може повторно використовуватися, якщо повідомлення передаються різними каналами зв'язку"]},{"id":"n19","t":"crypto","q":"Яка мінімальна довжина ключа RSA вважається прийнятною для сучасних систем за рекомендаціями NIST?","a":["2048 біт (для довгострокового захисту — 3072 біти і більше)","512 біт, оскільки довші ключі суттєво уповільнюють шифрування без покращення безпеки","1024 біти, оскільки цього достатньо для захисту від сучасних кластерів та квантових комп'ютерів","256 біт, адже довжини ключа RSA та AES за стійкістю повністю еквівалентні"]},{"id":"n20","t":"crypto","q":"Що таке Certificate Pinning (закріплення сертифіката)?","a":["Техніка, за якої застосунок довіряє лише наперед визначеному сертифікату або відкритому ключу сервера, ігноруючи інші довірені центри","Додавання сертифіката користувача до списку довірених сертифікатів операційної системи для всіх застосунків","Збереження резервної копії закритого ключа сервера в захищеному сховищі, прикріпленому до облікового запису адміністратора","Прикріплення цифрового підпису до електронного листа в тілі повідомлення в стиснутому вигляді"]},{"id":"n21","t":"crypto","q":"Який розмір блоку та довжину ключа має шифр за ДСТУ ГОСТ 28147:2009?","a":["Блок 64 біти, ключ 256 біт","Блок 128 біт, ключ 128 біт","Блок 256 біт, ключ 512 біт","Блок 32 біти, ключ 64 біти"]},{"id":"n22","t":"crypto","q":"Як протоколи захищаються від атаки повторного відтворення (Replay Attack)?","a":["Використанням одноразових значень (nonce), лічильників або часових міток, які перевіряє одержувач","Збільшенням довжини ключа шифрування до 4096 біт та використанням складніших алгоритмів гешування","Передаванням усіх повідомлень лише через VPN-тунель без додаткових перевірок на прикладному рівні","Вимкненням підтримки TCP на користь UDP, щоб унеможливити повторне надсилання пакетів"]},{"id":"n23","t":"crypto","q":"Що таке ChaCha20-Poly1305?","a":["AEAD-схема: потоковий шифр ChaCha20 разом з кодом автентичності Poly1305, що забезпечує конфіденційність та цілісність","Асиметричний алгоритм цифрового підпису на основі еліптичних кривих для використання в мобільних застосунках","Геш-функція з фіксованою довжиною дайджесту 512 біт, що використовується для зберігання паролів","Протокол узгодження ключів на основі Діффі-Геллмана для захищених з'єднань між маршрутизаторами"]},{"id":"n24","t":"crypto","q":"Яке призначення електронної позначки часу (Time-Stamp) у складі електронного підпису?","a":["Засвідчує, що електронний документ існував у незмінному вигляді на певний момент часу","Визначає термін дії сертифіката відкритого ключа та забезпечує його автоматичне продовження після завершення терміну","Фіксує IP-адресу пристрою, з якого було створено підпис, для можливого подальшого розслідування","Шифрує підписаний документ ключем центру сертифікації для захисту від несанкціонованого читання"]},{"id":"n25","t":"crypto","q":"Що таке стеганографія?","a":["Приховування самого факту існування повідомлення, наприклад у зображенні, аудіо або іншому контейнері","Перетворення повідомлення на незрозумілий вигляд за допомогою ключа так, що воно залишається видимим","Створення цифрового відбитка документа для перевірки його цілісності без використання секретного ключа","Метод аналізу шифротексту для визначення частоти символів та відновлення ключа"]},{"id":"n26","t":"crypto","q":"Яку довжину має дайджест (геш-значення) алгоритму MD5?","a":["128 біт","160 біт","256 біт","64 біти"]},{"id":"n27","t":"crypto","q":"Яку роль у PKI виконує центр сертифікації (CA)?","a":["Підписує сертифікати відкритих ключів, засвідчуючи зв'язок ключа із суб'єктом, та публікує інформацію про їх статус","Генерує та зберігає закриті ключі всіх користувачів, видаючи їх на вимогу після автентифікації","Шифрує трафік між клієнтами та серверами, виступаючи посередником у кожному сеансі зв'язку","Перевіряє наявність вразливостей у програмному забезпеченні, що використовує сертифікати"]},{"id":"n28","t":"kszi","q":"Який етап створення КСЗІ є першим відповідно до НД ТЗІ 3.7-003-2005?","a":["Формування вимог до захисту інформації в автоматизованій системі","Розроблення робочої документації та налаштування засобів захисту","Проведення державної експертизи та отримання атестата відповідності","Введення КСЗІ в дію та навчання користувачів роботі із засобами захисту"]},{"id":"n29","t":"kszi","q":"Що таке політика безпеки інформації?","a":["Сукупність документованих правил, процедур і практичних прийомів, що регламентують порядок захисту інформації в організації","Перелік програмних та апаратних засобів захисту, що встановлені в автоматизованій системі, з вказівкою виробників","Звіт про проведені тестування на проникнення із переліком виявлених вразливостей та рекомендацій щодо їх усунення","Методика розрахунку розміру збитків від можливих інцидентів за кожним активом організації"]},{"id":"n30","t":"kszi","q":"Що описує модель порушника в КСЗІ?","a":["Категорії порушників, їх мотивацію, кваліфікацію, технічну оснащеність та можливі дії щодо системи","Нормативно-правові акти, за порушення яких настає відповідальність у вигляді штрафів і адміністративних стягнень","Перелік програмних вразливостей та способів їх усунення за результатами останнього сканування мережі","Алгоритми дій адміністратора при виявленні порушення політики безпеки в роботі працівників"]},{"id":"n31","t":"kszi","q":"У чому полягає принцип найменших привілеїв (Least Privilege)?","a":["Користувачі та процеси отримують лише ті права, які мінімально необхідні для виконання їхніх завдань","Усі користувачі мають однакові права доступу, щоб уникнути конфліктів і спростити адміністрування системи","Адміністратор має повні права доступу, а звичайні користувачі працюють без будь-яких прав у системі","Права доступу надаються на найкоротший термін, після чого автоматично поновлюються без перегляду"]},{"id":"n32","t":"kszi","q":"У чому полягає принцип розподілу обов'язків (Separation of Duties)?","a":["Критичну операцію не може виконати самостійно одна особа: потрібна участь кількох, що знижує ризик зловживань та помилок","Кожен працівник виконує лише одну функцію протягом усього терміну роботи і не може змінювати посаду","Адміністратор системи не має права створювати користувачів без письмового дозволу керівника підрозділу","Обов'язки між підрозділами розподіляються так, щоб кожен захищав лише власні ресурси незалежно від інших"]},{"id":"n33","t":"kszi","q":"Що таке рольове розмежування доступу (RBAC)?","a":["Модель, у якій права доступу надаються ролям, а користувачам призначаються ролі відповідно до їхніх посад","Модель, у якій власник ресурсу сам вирішує, кому надавати доступ, і може передавати права іншим користувачам","Модель, у якій доступ визначається міткою секретності об'єкта та рівнем допуску суб'єкта без участі власника","Модель, у якій права вираховуються на основі атрибутів середовища, таких як час доби та геолокація"]},{"id":"n34","t":"kszi","q":"Що таке Honeypot («горщик з медом») у системі захисту?","a":["Навмисно вразлива система-приманка, що імітує реальний ресурс і дозволяє виявляти та вивчати дії зловмисників","Сервер резервного копіювання, що знаходиться в окремій локації та автоматично приймає навантаження під час аварій","Виділений сегмент мережі, у якому розміщені публічні сервіси організації, відокремлені від внутрішніх ресурсів","Програмний модуль, що маскує реальні IP-адреси внутрішніх вузлів за допомогою динамічної трансляції"]},{"id":"n35","t":"kszi","q":"Що таке DMZ (демілітаризована зона) у мережевій архітектурі?","a":["Сегмент мережі між зовнішньою та внутрішньою мережами, де розміщуються публічні сервіси з обмеженим доступом до внутрішніх ресурсів","Ізольований сегмент без підключення до будь-яких інших мереж, у якому обробляється інформація з грифом секретності","Зона, у якій вимкнено будь-яку фільтрацію трафіку для тестування нових сервісів перед запуском у виробництво","Резервна мережа, що автоматично вмикається у разі виходу з ладу основних каналів зв'язку з Інтернетом"]},{"id":"n36","t":"kszi","q":"Чим IPS (система запобігання вторгненням) відрізняється від IDS (система виявлення вторгнень)?","a":["IPS працює в розриві каналу та може автоматично блокувати шкідливий трафік, а IDS лише виявляє й сповіщає","IDS працює в розриві каналу й блокує трафік, а IPS пасивно прослуховує дзеркальний трафік і лише записує події","IPS захищає тільки мережеві пристрої, а IDS — виключно робочі станції користувачів із встановленим агентом","IPS використовує лише сигнатурний метод, а IDS — виключно аналіз аномалій і машинне навчання"]},{"id":"n37","t":"kszi","q":"Що таке багатофакторна автентифікація?","a":["Підтвердження особи з використанням щонайменше двох незалежних факторів: що знає користувач, чим володіє та що він собою являє","Введення пароля двічі у різних вікнах системи, що зменшує ймовірність помилки та перехоплення комбінації стороннім спостерігачем","Використання кількох різних паролів для різних облікових записів, що зберігаються в одному захищеному менеджері паролів на пристрої користувача","Автентифікація на кількох серверах одночасно, коли користувач послідовно вводить один і той самий пароль"]},{"id":"n38","t":"kszi","q":"Що таке NAC (Network Access Control) та стандарт IEEE 802.1X?","a":["Контроль доступу до мережі, коли пристрій отримує доступ до порту чи Wi-Fi лише після успішної автентифікації","Система автоматичного розподілу пропускної здатності каналу між застосунками залежно від їх пріоритету","Протокол динамічної маршрутизації, що обирає найкоротший шлях між мережами для передавання даних","Технологія агрегації каналів, що об'єднує кілька фізичних портів у один логічний для підвищення швидкості"]},{"id":"n39","t":"kszi","q":"Що передбачає принцип «захист у глибину» (Defense in Depth)?","a":["Побудову кількох незалежних рівнів захисту, щоб злам одного рівня не призводив до компрометації всієї системи","Концентрацію всіх засобів захисту на периметрі мережі з метою максимального посилення зовнішнього кордону","Заглиблення серверних приміщень під землю для захисту від фізичних атак та електромагнітного випромінювання","Використання одного універсального програмного продукту, що забезпечує всі функції безпеки з єдиної консолі"]},{"id":"n40","t":"kszi","q":"Що таке hardening (посилення захисту) системи?","a":["Зменшення поверхні атаки через видалення зайвих сервісів, закриття портів, зміну налаштувань за замовчуванням та встановлення оновлень","Збільшення продуктивності системи за рахунок оптимізації налаштувань та вимкнення механізмів журналювання подій і непотрібних перевірок цілісності","Створення резервної копії системи та перевірка можливості її відновлення на іншому обладнанні з документуванням результатів","Підвищення фізичної міцності корпусу сервера та встановлення додаткових замків на дверях серверної кімнати"]},{"id":"n41","t":"net","q":"Який стандартний порт використовує протокол HTTPS?","a":["443 (TCP)","80 (TCP)","8443 (UDP)","22 (TCP)"]},{"id":"n42","t":"net","q":"Який порт і транспортний протокол використовує служба DNS для звичайних запитів?","a":["Порт 53 (переважно UDP, TCP — для великих відповідей)","Порт 67 (UDP) для всіх запитів та відповідей","Порт 25 (TCP) для стандартних запитів зіставлення імен","Порт 110 (TCP) і 995 (TCP) з обов'язковим шифруванням"]},{"id":"n43","t":"net","q":"Який протокол автоматично видає клієнтам IP-адреси, маски та шлюзи в локальній мережі?","a":["DHCP (Dynamic Host Configuration Protocol)","ARP (Address Resolution Protocol)","ICMP (Internet Control Message Protocol)","NTP (Network Time Protocol)"]},{"id":"n44","t":"net","q":"Яку функцію виконує протокол ARP?","a":["Визначає MAC-адресу вузла за відомою IP-адресою в локальній мережі","Визначає IP-адресу вузла за доменним іменем, звертаючись до DNS-серверів","Автоматично призначає IP-адреси новим пристроям під час підключення до мережі","Обчислює найкоротший маршрут до віддаленої мережі, обмінюючись таблицями маршрутизації"]},{"id":"n45","t":"net","q":"Скільки адрес хостів доступно в підмережі з маскою 255.255.255.0 (/24)?","a":["254","256","255","510"]},{"id":"n46","t":"net","q":"Який стандартний порт використовує протокол SSH?","a":["22 (TCP)","23 (TCP)","21 (TCP)","3389 (TCP)"]},{"id":"n47","t":"net","q":"На якому рівні моделі OSI працюють маршрутизатори під час пересилання пакетів між мережами?","a":["Мережевому (L3)","Канальному (L2)","Транспортному (L4)","Сеансовому (L5)"]},{"id":"n48","t":"net","q":"Яка головна відмінність TCP від UDP?","a":["TCP встановлює з'єднання та гарантує доставку й порядок даних, UDP передає дейтаграми без підтвердження","TCP не гарантує доставку та працює швидше, а UDP підтверджує кожен пакет і забезпечує порядок","TCP працює на канальному рівні, а UDP — на мережевому, тому вони використовуються для різних типів адрес","TCP використовується лише для електронної пошти, а UDP — лише для вебсторінок та потокового відео"]},{"id":"n49","t":"net","q":"Яка часова складність бінарного пошуку у відсортованому масиві?","a":["O(log n)","O(n)","O(1)","O(n²)"]},{"id":"n50","t":"net","q":"Чим процес відрізняється від потоку (thread) в операційній системі?","a":["Процес має власний адресний простір, а потоки одного процесу спільно використовують його пам'ять і ресурси","Потік має власний адресний простір, а процеси одного застосунку спільно використовують його пам'ять","Процес завжди виконується в режимі ядра, а потік — виключно в режимі користувача без доступу до пам'яті","Процес призначений для введення-виведення, а потік — лише для обчислень на процесорі"]},{"id":"n51","t":"net","q":"Для чого призначені VLAN (віртуальні локальні мережі)?","a":["Логічно розділяють одну фізичну мережу на окремі широкомовні домени, підвищуючи керованість і безпеку","Об'єднують кілька географічно віддалених офісів в одну мережу з шифруванням трафіку між ними","Збільшують швидкість каналу, об'єднуючи кілька фізичних кабелів в один логічний інтерфейс","Автоматично розподіляють IP-адреси пристроям залежно від їх типу та виробника мережевої карти"]},{"id":"n52","t":"net","q":"Чим контейнер Docker відрізняється від віртуальної машини з точки зору ізоляції?","a":["Контейнери використовують спільне ядро хост-системи, а віртуальна машина має власне ядро гостьової ОС","Контейнери мають власне ядро та апаратну віртуалізацію, а віртуальна машина використовує ядро хоста","Контейнери повністю ізольовані на апаратному рівні, тому вразливості ядра хоста на них не впливають","Віртуальні машини не потребують гіпервізора, на відміну від контейнерів, які працюють лише з ним"]},{"id":"n53","t":"net","q":"Яка структура даних працює за принципом LIFO («останнім прийшов — першим вийшов»)?","a":["Стек","Черга","Двозв'язний список","Хеш-таблиця"]},{"id":"n54","t":"netsec","q":"У чому полягає суть DDoS-атаки?","a":["Одночасні запити з великої кількості джерел перевантажують ресурс і роблять його недоступним для легітимних користувачів","Зловмисник отримує доступ до облікового запису адміністратора шляхом підбору пароля з використанням словника","Шкідливий код шифрує файли користувачів і вимагає викуп за ключ розшифрування","Підроблені DNS-відповіді спрямовують користувачів на сайт зловмисника, який імітує справжній ресурс"]},{"id":"n55","t":"netsec","q":"Що забезпечує стандарт IEEE 802.1X?","a":["Порт-орієнтовану автентифікацію пристроїв за допомогою EAP до надання доступу до мережі","Шифрування трафіку на канальному рівні між усіма пристроями однієї VLAN за допомогою ключів DHCP","Автоматичне агрегування каналів між комутаторами для підвищення пропускної здатності та відмовостійкості","Динамічну маршрутизацію між автономними системами з перевіркою походження префіксів"]},{"id":"n56","t":"netsec","q":"Яка перевага протоколу SAE (Dragonfly) у WPA3-Personal порівняно з WPA2-PSK?","a":["Стійкість до офлайн-підбору пароля за перехопленим рукостисканням та пряма таємність сеансових ключів","Відсутність необхідності в паролі, оскільки пристрої автентифікуються за MAC-адресами при підключенні","Використання відкритого ключа сервера, що зберігається на кожному пристрої для автоматичного підключення","Збільшення дальності дії Wi-Fi мережі завдяки зменшенню накладних витрат на шифрування"]},{"id":"n57","t":"netsec","q":"Яка атака полягає в переповненні таблиці MAC-адрес комутатора великою кількістю підроблених кадрів?","a":["MAC Flooding (переповнення CAM-таблиці)","ARP Spoofing (підміна ARP-відповідей)","DHCP Starvation (вичерпання пулу адрес)","VLAN Hopping (перестрибування між VLAN)"]},{"id":"n58","t":"netsec","q":"Яка функція захищає від підключення сторонніх комутаторів, що можуть стати кореневим мостом у мережі з STP?","a":["Root Guard / BPDU Guard","Dynamic ARP Inspection","DHCP Snooping","Storm Control"]},{"id":"n59","t":"netsec","q":"Для чого використовується протокол DKIM в електронній пошті?","a":["Для цифрового підпису листів на рівні домену, що дозволяє перевірити їх автентичність і незмінність","Для вказівки переліку серверів, які мають право надсилати пошту від імені домену відправника","Для шифрування вмісту листів між поштовим сервером та клієнтом за допомогою TLS","Для автоматичного видалення спаму на поштовому сервері на основі репутації IP-адрес"]},{"id":"n60","t":"netsec","q":"Яка ключова відмінність SPF від DKIM та DMARC?","a":["SPF перевіряє, чи має IP-адреса відправника право надсилати пошту від імені домену, DKIM підписує листи, DMARC задає політику обробки перевірок","SPF підписує листи цифровим підписом, DKIM перелічує дозволені сервери, а DMARC шифрує вміст повідомлення під час його передавання між серверами","SPF шифрує вкладення, DKIM перевіряє відправника за IP-адресою, DMARC видаляє шкідливе програмне забезпечення з листів на стороні одержувача незалежно від політик домену","SPF, DKIM та DMARC є різними назвами одного протоколу, що використовується різними поштовими провайдерами"]},{"id":"n61","t":"netsec","q":"Що забезпечує механізм HSTS (HTTP Strict Transport Security)?","a":["Змушує браузер використовувати лише HTTPS для певного домену, що запобігає атакам SSL Stripping","Шифрує вміст куки та передає їх виключно в заголовках, недоступних для JavaScript","Блокує завантаження скриптів та зображень із сторонніх доменів на сторінках сайту","Автоматично оновлює сертифікат сервера перед завершенням терміну його дії без участі адміністратора"]},{"id":"n62","t":"netsec","q":"Як слід безпечно організувати доступ до RDP-серверів (порт 3389)?","a":["Не виставляти порт в Інтернет, надавати доступ через VPN або шлюз із MFA та вмикати автентифікацію на рівні мережі (NLA)","Змінити стандартний порт на нестандартний і вважати цього достатнім для захисту від сканерів та автоматизованих атак підбору","Відкрити порт для всіх адрес, обмеживши час сесії до 5 хвилин, щоб ускладнити підбір паролів та зменшити навантаження на сервер","Вимкнути журналювання подій на сервері, щоб зловмисники не могли виявити спроби входу та не отримували відомостей про налаштування системи"]},{"id":"n63","t":"netsec","q":"Яка перевага мережевої сегментації з точки зору безпеки?","a":["Обмежує поширення атаки (латеральне переміщення) та дозволяє застосовувати різні політики до різних сегментів","Збільшує швидкість передавання даних між усіма вузлами за рахунок використання єдиного широкомовного домену","Усуває необхідність у міжмережевих екранах, оскільки сегменти автоматично блокують шкідливий трафік","Дозволяє використовувати однакові IP-адреси в різних сегментах без обмежень і додаткового налаштування"]},{"id":"n64","t":"netsec","q":"Як працює атака Slowloris?","a":["Зловмисник утримує безліч напіввідкритих HTTP-з'єднань, повільно надсилаючи частини заголовків і вичерпуючи ресурси сервера","Зловмисник надсилає великі UDP-пакети з підміненою адресою жертви на відкриті рекурсивні DNS-сервери","Зловмисник використовує вразливість форми для впровадження SQL-коду і повільно зчитує вміст бази даних через відповіді застосунку","Зловмисник нескінченно повторює запити на оновлення ARP-таблиці комутатора, перевантажуючи його процесор і пам'ять"]},{"id":"n65","t":"netsec","q":"У чому суть атаки SSL Stripping і чим від неї захищаються?","a":["Зловмисник змушує клієнта працювати по HTTP замість HTTPS; захист — HSTS та перенаправлення на HTTPS","Зловмисник підбирає закритий ключ сервера; захист — використання ключів довжиною понад 4096 біт","Зловмисник знижує версію TLS до 1.0 на стороні клієнта; захист — вимкнення підтримки cookies","Зловмисник підміняє сертифікат центру сертифікації; захист — використання паролів довжиною 16 символів"]},{"id":"n66","t":"os","q":"Яке призначення механізму UAC (User Account Control) у Windows?","a":["Запитує підтвердження підвищення привілеїв перед виконанням дій, що вимагають прав адміністратора","Шифрує профіль користувача та вміст диска за допомогою ключа, що зберігається в модулі TPM","Блокує запуск програм, не підписаних цифровим підписом виробника, незалежно від налаштувань користувача","Контролює мережевий трафік застосунків та створює правила міжмережевого екрана автоматично"]},{"id":"n67","t":"os","q":"Що означають права доступу chmod 640 для файлу в Linux?","a":["Власник може читати й записувати, група — лише читати, інші користувачі не мають доступу","Власник може читати й виконувати, група — записувати, інші користувачі — лише читати","Власник має всі права, група — читати й записувати, інші користувачі — лише виконувати","Власник може лише читати, група — читати й записувати, інші користувачі — читати й виконувати"]},{"id":"n68","t":"os","q":"У якому файлі Linux зберігаються геші паролів локальних користувачів?","a":["/etc/shadow","/etc/passwd","/etc/group","/var/log/auth.log"]},{"id":"n69","t":"os","q":"Чим SELinux та AppArmor відрізняються від класичних прав доступу Linux (DAC)?","a":["Реалізують обов'язкове розмежування доступу (MAC): політика задається адміністратором і діє навіть для користувача root","Реалізують дискреційне розмежування, у якому власник файлу сам вирішує, хто може отримати до нього доступ","Шифрують файлову систему на рівні ядра та автоматично змінюють ключі при перезавантаженні системи","Забороняють використання мережевих інтерфейсів усім процесам, які не належать користувачу root"]},{"id":"n70","t":"os","q":"Яка подія Windows Security фіксує невдалу спробу входу в систему?","a":["Event ID 4625","Event ID 4624","Event ID 4720","Event ID 1102"]},{"id":"n71","t":"os","q":"Який процес Windows є основною ціллю інструментів на кшталт Mimikatz для витягування облікових даних із пам'яті?","a":["lsass.exe (Local Security Authority Subsystem Service)","explorer.exe (Windows Explorer)","svchost.exe (Service Host для служби Print Spooler)","winlogon.exe лише у режимі безпечного завантаження"]},{"id":"n72","t":"os","q":"Що забезпечує технологія BitLocker?","a":["Повне шифрування томів диска з можливістю використання TPM для зберігання ключів","Шифрування окремих файлів і папок за допомогою сертифіката користувача (EFS) без захисту системного розділу","Блокування несанкціонованих змін системних файлів та реєстру шляхом перевірки цифрових підписів","Ізоляцію облікових даних у віртуальному контейнері, що захищає їх від крадіжки з пам'яті"]},{"id":"n73","t":"os","q":"Для чого призначений механізм Secure Boot (UEFI)?","a":["Перевіряє цифрові підписи завантажувача та драйверів під час старту, запобігаючи запуску недовіреного коду","Шифрує вміст диска при завантаженні та вимагає введення пароля для розблокування системного розділу","Захищає BIOS від зміни пароля адміністратора й блокує завантаження з USB-накопичувачів","Автоматично відновлює пошкоджені системні файли із резервної копії перед запуском операційної системи"]},{"id":"n74","t":"os","q":"Що робить команда sudo в Linux?","a":["Виконує команду з привілеями іншого користувача (зазвичай root) відповідно до політики, заданої в /etc/sudoers","Змінює власника файлу на користувача root і встановлює біт SUID для подальшого запуску","Створює нового користувача з правами адміністратора та генерує для нього пароль","Блокує доступ до системи для всіх користувачів, окрім root, на час проведення обслуговування"]},{"id":"n75","t":"os","q":"Що означає встановлений sticky bit на каталозі (наприклад, /tmp)?","a":["Видаляти або перейменовувати файли в каталозі може лише їх власник (або власник каталогу чи root)","Усі файли в каталозі запускаються з правами власника каталогу, а не з правами користувача","Нові файли в каталозі автоматично успадковують групу каталогу та не можуть бути змінені","Вміст каталогу автоматично шифрується при записі та розшифровується для власника файлів"]},{"id":"n76","t":"os","q":"Яке призначення рішення Microsoft LAPS?","a":["Автоматично генерує унікальні випадкові паролі локальних адміністраторів на кожному комп'ютері та зберігає їх у каталозі","Централізовано встановлює оновлення безпеки на всіх комп'ютерах домену відповідно до розкладу та звітує про їх стан у консолі","Блокує вхід локальних адміністраторів на комп'ютери, що не входять до складу домену, і журналює всі спроби такого входу","Налаштовує однаковий пароль адміністратора для всіх комп'ютерів, щоб спростити обслуговування"]},{"id":"n77","t":"os","q":"Що таке руткіт (rootkit)?","a":["Шкідливе ПЗ, що приховує свою присутність та інші зловмисні процеси чи файли, часто діючи на рівні ядра","Програма, що шифрує файли користувача та вимагає викуп за відновлення доступу до них","Скрипт, що автоматично збирає паролі з браузера та відправляє їх на віддалений сервер зловмисника","Утиліта адміністратора для віддаленого керування системою з максимальними правами за ліцензією"]},{"id":"n78","t":"os","q":"Яка підсистема Linux призначена для ведення детального аудиту системних викликів та доступу до файлів?","a":["auditd (Linux Audit Framework)","cron (планувальник завдань)","systemd-resolved (служба розв'язання імен)","logrotate (ротація журналів)"]},{"id":"n79","t":"swsec","q":"Що таке OWASP Top 10?","a":["Регулярно оновлюваний перелік десяти найкритичніших категорій ризиків безпеки вебзастосунків","Перелік десяти найпопулярніших інструментів для тестування на проникнення, рекомендованих спільнотою","Стандарт шифрування з десятьма обов'язковими алгоритмами для захисту даних у веббраузерах","Рейтинг десяти найбільших хакерських груп за кількістю успішних атак на державні сайти"]},{"id":"n80","t":"swsec","q":"У чому полягає вразливість IDOR (Insecure Direct Object Reference)?","a":["Зміна ідентифікатора об'єкта в запиті дозволяє отримати доступ до чужих даних через відсутність перевірки прав","Передача паролів у відкритому вигляді в URL-адресах без використання захищеного протоколу HTTPS","Можливість виконати довільний код на сервері через небезпечну десеріалізацію вхідних об'єктів","Відсутність обмеження на кількість запитів, що дозволяє підбирати паролі методом перебору"]},{"id":"n81","t":"swsec","q":"Що таке переповнення буфера (Buffer Overflow)?","a":["Запис у буфер більшої кількості даних, ніж він здатен вмістити, що призводить до перезапису сусідньої пам'яті","Вичерпання вільної оперативної пам'яті внаслідок витоку, коли програма не звільняє виділені блоки","Помилка округлення при обчисленні цілих чисел, що призводить до виходу значення за допустимий діапазон","Одночасний доступ двох потоків до спільного ресурсу, що призводить до непередбачуваного стану"]},{"id":"n82","t":"swsec","q":"У чому полягає атака Path Traversal (обхід каталогів)?","a":["Використання послідовностей на кшталт ../ у параметрах для доступу до файлів поза межами дозволеного каталогу","Впровадження шкідливого скрипту в параметр URL, що виконується у браузері користувача під час відкриття посилання","Підбір імен каталогів на сервері за словником для виявлення прихованих адміністративних розділів сайту","Перенаправлення користувача на сторонній сайт через параметр redirect без перевірки домену"]},{"id":"n83","t":"swsec","q":"Яка ефективна комбінація заходів захисту від XSS?","a":["Контекстне екранування (кодування) виводу, валідація вхідних даних та політика Content Security Policy","Параметризовані SQL-запити разом із використанням збережених процедур на стороні бази даних","Використання токенів CSRF разом із встановленням атрибута SameSite для всіх сесійних cookies","Шифрування трафіку протоколом TLS 1.3 і підписування всіх скриптів цифровим сертифікатом"]},{"id":"n84","t":"swsec","q":"Що робить прапорець HttpOnly для cookie?","a":["Забороняє доступ до cookie із клієнтського JavaScript, що ускладнює її викрадення через XSS","Дозволяє передавати cookie виключно за захищеним протоколом HTTPS і блокує передавання по HTTP","Забороняє надсилання cookie під час міжсайтових запитів, що захищає від CSRF-атак","Обмежує термін життя cookie до завершення сеансу браузера без збереження на диску"]},{"id":"n85","t":"swsec","q":"Яка різниця між SAST та DAST?","a":["SAST аналізує вихідний код без запуску застосунку, а DAST тестує працюючий застосунок ззовні, імітуючи атаки","SAST тестує працюючий застосунок зовні, а DAST аналізує вихідний код без його запуску","SAST перевіряє лише мережеву інфраструктуру, а DAST — виключно конфігурацію баз даних","SAST виконується тільки на етапі експлуатації, а DAST — виключно після закінчення тестування"]},{"id":"n86","t":"swsec","q":"Що таке SBOM (Software Bill of Materials)?","a":["Формалізований перелік компонентів і залежностей програмного продукту, що допомагає керувати ризиками ланцюга постачання","Звіт про результати тестування на проникнення із переліком знайдених вразливостей та рівнем їх критичності","Підписаний сертифікат, що підтверджує відповідність програмного продукту вимогам стандарту безпеки","Розрахунок вартості розроблення програмного забезпечення із зазначенням ресурсів, які використовувалися"]},{"id":"n87","t":"swsec","q":"Що таке фаззинг (fuzzing)?","a":["Автоматичне подавання на вхід програми великої кількості некоректних або випадкових даних для виявлення збоїв та вразливостей","Статичний аналіз бінарного файла для відновлення вихідного коду та пошуку захардкоджених паролів у виконуваних модулях програми","Перебір паролів і логінів за словником для визначення слабких місць автентифікації у вебзастосунках та мережевих сервісах","Формальна верифікація алгоритмів математичними методами для доведення відсутності помилок"]},{"id":"n88","t":"swsec","q":"У чому полягає атака впровадження команд ОС (Command Injection)?","a":["Передача в параметрах символів, що дозволяють виконати довільні системні команди на сервері через небезпечний виклик оболонки","Впровадження SQL-запиту у вхідні дані з метою зчитування або зміни вмісту бази даних застосунку через форму введення","Використання вразливого парсера XML для читання локальних файлів сервера через зовнішні сутності","Підміна заголовка Host у запиті для отримання доступу до внутрішніх вебсервісів компанії"]},{"id":"n89","t":"swsec","q":"Чому небезпечно зберігати паролі, токени та ключі API безпосередньо в коді (hardcoded secrets)?","a":["Вони потрапляють у систему контролю версій та артефакти збирання, звідки їх можуть отримати сторонні особи","Це збільшує розмір програми та уповільнює її запуск, оскільки секрети постійно перевіряються при ініціалізації","Компілятори автоматично видаляють такі рядки, тому застосунок перестає працювати після оптимізації","Секрети в коді швидко застарівають, оскільки алгоритми шифрування змінюються щомісяця за вимогами стандартів"]},{"id":"n90","t":"swsec","q":"Що таке небезпечна десеріалізація (Insecure Deserialization)?","a":["Відновлення об'єктів із недовірених даних без перевірки, що може призвести до виконання коду або порушення логіки застосунку","Перетворення об'єктів у текстовий формат без шифрування, внаслідок чого дані читаються при передаванні мережею стороннім спостерігачем","Втрата частини даних під час перетворення складних об'єктів у JSON через обмеження розміру поля та помилки кодування символів","Використання застарілих бібліотек, які не підтримують сучасні формати даних, такі як XML та YAML"]},{"id":"n91","t":"swsec","q":"Що означає принцип Security by Design?","a":["Вимоги безпеки враховуються на всіх етапах життєвого циклу розроблення, починаючи з проєктування","Захист додається до готового продукту наприкінці розробки шляхом тестування й усунення вразливостей","Продукт розробляється розробниками, які мають сертифікат з кібербезпеки, без участі інших фахівців","Безпека забезпечується виключно периметровими засобами, а код застосунку може бути довільним"]},{"id":"n92","t":"inc","q":"Яка фаза NIST SP 800-61 слідує за фазою «Виявлення та аналіз» (Detection & Analysis)?","a":["Стримування, ліквідація та відновлення (Containment, Eradication & Recovery)","Підготовка (Preparation)","Післяінцидентна діяльність (Post-Incident Activity)","Моніторинг та оцінювання (Monitoring & Assessment)"]},{"id":"n93","t":"inc","q":"Яка перша фаза моделі Cyber Kill Chain (Lockheed Martin)?","a":["Розвідка (Reconnaissance)","Озброєння (Weaponization)","Доставка (Delivery)","Експлуатація (Exploitation)"]},{"id":"n94","t":"inc","q":"Що таке MITRE ATT&CK?","a":["Загальнодоступна база знань про тактики й техніки атакуючих, що засновані на реальних спостереженнях","Міжнародний стандарт сертифікації систем управління інформаційною безпекою організації","Система бальної оцінки критичності вразливостей програмного забезпечення за шкалою від 0 до 10","Програмний комплекс для автоматичного реагування на інциденти й блокування шкідливої активності"]},{"id":"n95","t":"inc","q":"Що означає абревіатура APT у кібербезпеці?","a":["Advanced Persistent Threat — тривала цілеспрямована атака кваліфікованого зловмисника зі прихованою присутністю в мережі","Automated Penetration Testing — автоматичне тестування на проникнення з використанням готових скриптів","Application Protection Technology — технологія захисту застосунків від несанкціонованої модифікації коду","Advanced Password Tool — набір інструментів для швидкого підбору паролів до облікових записів"]},{"id":"n96","t":"inc","q":"Що таке подвійне вимагання (double extortion) у ransomware-атаках?","a":["Зловмисники шифрують дані та додатково викрадають їх, погрожуючи оприлюднити у разі несплати викупу","Зловмисники вимагають оплату двічі: спочатку за ключ розшифрування, а потім за видалення шкідливого коду","Шкідливе ПЗ шифрує файли двома різними алгоритмами, що ускладнює їх відновлення без ключа","Атака одночасно спрямовується на два підприємства-партнери для збільшення розміру вимагання"]},{"id":"n97","t":"inc","q":"Чим відрізняються команди Red Team та Blue Team?","a":["Red Team імітує дії атакуючих, а Blue Team захищає та виявляє атаки","Red Team відповідає за розроблення політик безпеки, а Blue Team — за закупівлю обладнання","Red Team проводить аудит відповідності стандартам, а Blue Team — тестує продуктивність мережі","Red Team працює лише з клієнтським обладнанням, а Blue Team — виключно із серверами"]},{"id":"n98","t":"inc","q":"Що таке тестування на проникнення типу «чорна скринька» (Black Box)?","a":["Тестувальник діє без попередніх знань про систему, подібно до зовнішнього зловмисника","Тестувальник має повний доступ до вихідного коду, схем та конфігурацій системи перед початком робіт","Тестувальник отримує обмежений набір відомостей, наприклад обліковий запис звичайного користувача","Тестування проводиться лише автоматичними сканерами без участі фахівця й без аналізу результатів"]},{"id":"n99","t":"inc","q":"Для чого використовується шкала CVSS?","a":["Для стандартизованої оцінки критичності вразливостей за шкалою від 0 до 10","Для визначення рівня зрілості процесів безпеки в організації за п'ятьма ступенями","Для розрахунку ймовірності реалізації загрози у відсотках для кожного активу організації","Для класифікації інцидентів за рівнем впливу на бізнес за чотирма категоріями"]},{"id":"n100","t":"inc","q":"Що таке вразливість нульового дня (zero-day)?","a":["Вразливість, невідома виробнику або без доступного виправлення, яку вже можуть експлуатувати зловмисники","Вразливість, виявлена протягом першої доби після випуску нової версії програмного забезпечення","Вразливість, що дозволяє зловмиснику отримати доступ до системи без автентифікації за нульового часу","Вразливість, усунена в день виявлення завдяки автоматичному оновленню безпеки"]},{"id":"n101","t":"inc","q":"Що таке C2 (Command and Control) сервер у контексті ботнету?","a":["Інфраструктура, через яку зловмисник керує зараженими пристроями та отримує від них дані","Резервний сервер організації, що автоматично запускається при збої основної системи та керує відновленням","Сервер у SOC, що збирає журнали подій від усіх систем і формує звіти для керівництва","Сервер оновлень антивірусу, що надсилає на пристрої нові сигнатури шкідливих програм"]},{"id":"n102","t":"inc","q":"Що таке латеральне переміщення (lateral movement)?","a":["Просування зловмисника мережею від скомпрометованого вузла до інших систем для розширення доступу","Підвищення привілеїв на скомпрометованому вузлі з рівня користувача до рівня адміністратора","Передавання викрадених даних за межі мережі організації за допомогою прихованих каналів","Перенесення шкідливого коду з одного носія на інший шляхом автоматичного копіювання файлів"]},{"id":"n103","t":"inc","q":"Для чого проводиться розбір інциденту (Lessons Learned) після його завершення?","a":["Для виявлення причин та слабких місць, оновлення процедур і запобігання повторенню інциденту","Для визначення винних працівників і застосування до них дисциплінарних заходів відповідно до політики","Для підготовки публічного звіту про інцидент та відновлення довіри клієнтів у засобах масової інформації","Для остаточного видалення всіх артефактів інциденту із систем з метою звільнення місця на дисках"]},{"id":"n104","t":"inc","q":"Для чого під час збору доказів використовують блокувальник запису (write blocker)?","a":["Щоб запобігти будь-яким змінам на носії під час його підключення та створення образу","Щоб зашифрувати носій перед передаванням експерту та захистити дані від стороннього доступу","Щоб автоматично видалити шкідливе програмне забезпечення з носія перед початком аналізу","Щоб прискорити копіювання даних за рахунок вимкнення перевірки файлової системи"]},{"id":"n105","t":"inc","q":"Що таке полювання на загрози (Threat Hunting)?","a":["Проактивний пошук ознак прихованої шкідливої активності в мережі, яку не виявили автоматичні засоби","Автоматичне сканування мережі на наявність відомих вразливостей за розкладом з формуванням звітів","Реагування на сповіщення SIEM та закриття заявок відповідно до регламенту служби підтримки","Збір інформації про зловмисників із відкритих джерел для підготовки аналітичних оглядів"]},{"id":"n106","t":"inc","q":"Що характерно для атаки на ланцюг постачання (Supply Chain Attack), як-от компрометація оновлення SolarWinds?","a":["Зловмисник компрометує довіреного постачальника, щоб доставити шкідливий код клієнтам через легітимні оновлення","Зловмисник перехоплює фізичні поставки обладнання та встановлює в нього апаратні закладки під час транспортування","Зловмисник блокує роботу логістичних систем підприємства шляхом перевантаження серверів великою кількістю запитів","Зловмисник підроблює накладні та рахунки-фактури, надсилаючи їх бухгалтерам від імені постачальників"]},{"id":"n107","t":"risk","q":"Як розраховуються очікувані річні втрати (ALE) у кількісному аналізі ризиків?","a":["ALE = SLE × ARO (одноразові втрати × річна частота події)","ALE = SLE + ARO (одноразові втрати + річна частота події)","ALE = AV ÷ EF (вартість активу, поділена на фактор впливу)","ALE = ARO × EF (річна частота, помножена на фактор впливу)"]},{"id":"n108","t":"risk","q":"Як розраховуються очікувані разові втрати (SLE)?","a":["SLE = вартість активу (AV) × фактор впливу (EF)","SLE = вартість активу (AV) × річна частота події (ARO)","SLE = вартість активу (AV) + вартість контрзаходу","SLE = ймовірність події ÷ кількість активів"]},{"id":"n109","t":"risk","q":"Що таке залишковий ризик (residual risk)?","a":["Ризик, що залишається після застосування заходів зменшення ризику","Ризик, який виникає внаслідок помилок співробітників під час впровадження нових систем","Загальний ризик до застосування будь-яких заходів, що визначає початковий рівень загрози","Ризик, переданий третій стороні за договором страхування або аутсорсингу"]},{"id":"n110","t":"risk","q":"Що таке апетит до ризику (risk appetite) організації?","a":["Рівень і вид ризику, який організація готова прийняти для досягнення своїх цілей","Максимальна сума страхового покриття, на яку організація може розраховувати у разі інциденту","Кількість ризиків, які вдалося виявити за допомогою автоматизованих засобів оцінювання","Перелік загроз, що вважаються неймовірними та тому не підлягають аналізу"]},{"id":"n111","t":"risk","q":"У чому різниця між стандартами ISO/IEC 27001 та ISO/IEC 27002?","a":["27001 містить вимоги до СУІБ (сертифікується), 27002 — настанови щодо впровадження заходів безпеки","27001 є настановою щодо заходів безпеки, а 27002 містить вимоги до СУІБ, за якими здійснюють сертифікацію","27001 описує управління ризиками, а 27002 — лише процедури резервного копіювання та відновлення","27001 стосується тільки державних організацій, а 27002 застосовується виключно у приватному секторі"]},{"id":"n112","t":"risk","q":"Який стандарт визначає вимоги до системи управління безперервністю бізнесу (BCMS)?","a":["ISO 22301","ISO/IEC 27005","ISO 9001","ISO/IEC 20000-1"]},{"id":"n113","t":"risk","q":"Що описує NIST SP 800-53?","a":["Каталог заходів безпеки та приватності для інформаційних систем","Методику проведення тестування на проникнення та перевірки захищеності мереж","Рекомендації щодо реагування на інциденти інформаційної безпеки","Вимоги до криптографічних модулів та їх сертифікації за рівнями безпеки"]},{"id":"n114","t":"risk","q":"Чим якісний аналіз ризиків відрізняється від кількісного?","a":["Якісний використовує описові шкали (низький, середній, високий), а кількісний — числові значення та грошові втрати","Якісний ґрунтується на точних статистичних даних, а кількісний — на думках експертів та інтерв'ю","Якісний застосовується лише до апаратного забезпечення, а кількісний — тільки до програмного","Якісний виконується автоматично сканерами, а кількісний завжди потребує проведення аудиту"]},{"id":"n115","t":"risk","q":"Яка основна відмінність BCP від DRP?","a":["BCP забезпечує безперервність бізнес-процесів загалом, а DRP зосереджений на відновленні ІТ-інфраструктури після катастрофи","BCP описує лише відновлення серверів та баз даних, а DRP — управління персоналом під час кризи та взаємодію із засобами масової інформації","BCP застосовується тільки до державних установ, а DRP — виключно до комерційних підприємств незалежно від галузі їхньої діяльності","BCP розробляється після настання інциденту, а DRP — за кілька років до його ймовірного виникнення"]},{"id":"n116","t":"risk","q":"Що таке «гарячий» резервний майданчик (hot site)?","a":["Повністю обладнаний майданчик із актуальними даними, готовий до майже негайного перемикання","Майданчик із приміщенням та мінімальним обладнанням, що потребує тривалого розгортання систем","Резервне сховище зі стрічковими копіями, що зберігаються в сейфі та перевозяться за потреби","Майданчик, що розміщений у зоні підвищеної температури і використовується лише для тестування"]},{"id":"n117","t":"risk","q":"Що передбачає правило резервного копіювання 3-2-1?","a":["3 копії даних, на 2 різних типах носіїв, з 1 копією за межами основного майданчика","3 копії даних щодня, 2 копії щотижня та 1 копія щомісяця на одному носії","3 різні програми резервного копіювання, 2 адміністратори та 1 резервний сервер","3 копії в одному дата-центрі, 2 копії в хмарі та 1 копія на робочій станції"]},{"id":"n118","t":"risk","q":"Які основні етапи процесу управління ризиками інформаційної безпеки за ISO/IEC 27005?","a":["Встановлення контексту, оцінювання ризиків (ідентифікація, аналіз, порівняння), обробка ризиків, моніторинг і перегляд","Закупівля засобів захисту, їх впровадження, налаштування, навчання персоналу та проведення аудиту відповідності вимогам","Планування, виконання, перевірка та поліпшення без окремого етапу ідентифікації ризиків та без визначення контексту організації","Виявлення інциденту, його локалізація, ліквідація наслідків та складання звіту для керівництва"]},{"id":"n119","t":"risk","q":"Хто повинен затверджувати політику інформаційної безпеки організації?","a":["Вище керівництво організації","Підрозділ ІТ-підтримки за погодженням із постачальниками","Зовнішній аудитор під час сертифікаційного аудиту","Кожен керівник підрозділу самостійно для власної команди"]},{"id":"n120","t":"law","q":"Яка стаття Кримінального кодексу України передбачає відповідальність за несанкціоноване втручання в роботу інформаційних (автоматизованих) систем?","a":["Стаття 361 КК України","Стаття 190 КК України","Стаття 176 КК України","Стаття 200 КК України"]},{"id":"n121","t":"law","q":"Яка стаття КК України стосується створення з метою використання, розповсюдження або збуту шкідливих програмних засобів?","a":["Стаття 361-1","Стаття 361-2","Стаття 363","Стаття 364"]},{"id":"n122","t":"law","q":"Яка стаття КК України передбачає відповідальність за несанкціоновані дії з інформацією, що обробляється в ІТС (викрадення, зміна, знищення)?","a":["Стаття 362","Стаття 358","Стаття 359","Стаття 368"]},{"id":"n123","t":"law","q":"Який закон України регулює правовий статус електронного підпису та електронних довірчих послуг?","a":["Закон України «Про електронні довірчі послуги»","Закон України «Про захист персональних даних»","Закон України «Про доступ до публічної інформації»","Закон України «Про телекомунікації»"]},{"id":"n124","t":"law","q":"Який регламент ЄС встановлює правила електронної ідентифікації та довірчих послуг на внутрішньому ринку?","a":["Регламент (ЄС) № 910/2014 (eIDAS)","Регламент (ЄС) 2016/679 (GDPR)","Регламент (ЄС) 2019/881 (Cybersecurity Act)","Регламент (ЄС) 2022/2554 (DORA)"]},{"id":"n125","t":"law","q":"Який максимальний розмір адміністративного штрафу передбачено GDPR за найсерйозніші порушення?","a":["До 20 млн євро або до 4% річного світового обороту — залежно від того, що більше","До 1 млн євро або до 1% річного обороту компанії — залежно від того, що менше","До 50 млн євро незалежно від обороту, але лише для державних органів","До 100 тис. євро за кожну особу, чиї дані були порушені, без обмеження загальної суми"]},{"id":"n126","t":"law","q":"Протягом якого часу, згідно з NIS2, суттєві та важливі суб'єкти мають надіслати раннє попередження про значний інцидент?","a":["Протягом 24 годин з моменту виявлення","Протягом 72 годин з моменту виявлення","Протягом 7 діб з моменту виявлення","Протягом 30 діб після завершення розслідування"]},{"id":"n127","t":"law","q":"Що таке кіберінцидент згідно із законодавством України про основні засади кібербезпеки?","a":["Подія або ряд подій, що загрожують кібербезпеці й порушують чи можуть порушити конфіденційність, цілісність або доступність систем та даних","Будь-яке порушення правил експлуатації комп'ютерної техніки працівником, що призвело до її поломки","Факт виявлення вразливості в програмному забезпеченні, що використовується державними органами","Судове рішення, яким встановлено порушення законодавства у сфері захисту інформації"]},{"id":"n128","t":"law","q":"Який орган у структурі РНБО координує діяльність суб'єктів сектору безпеки і оборони у сфері кібербезпеки?","a":["Національний координаційний центр кібербезпеки (НКЦК)","Державна служба спеціального зв'язку та захисту інформації (як окремий орган за межами РНБО)","Урядова команда реагування на комп'ютерні надзвичайні події CERT-UA","Кіберполіція Національної поліції України"]},{"id":"n129","t":"law","q":"Яку кількість рівнів гарантій оцінювання (EAL) визначає ISO/IEC 15408 (Common Criteria)?","a":["Сім рівнів (EAL1–EAL7)","Три рівні (низький, середній, високий)","П'ять рівнів (EAL1–EAL5)","Десять рівнів (EAL0–EAL9)"]},{"id":"n130","t":"law","q":"Який підрозділ Національної поліції України займається протидією кіберзлочинності?","a":["Департамент кіберполіції","Департамент карного розшуку","Управління внутрішньої безпеки","Департамент стратегічних розслідувань"]},{"id":"n131","t":"law","q":"Яким законом України регулюється віднесення відомостей до державної таємниці та порядок доступу до неї?","a":["Закон України «Про державну таємницю»","Закон України «Про інформацію»","Закон України «Про доступ до публічної інформації»","Закон України «Про захист інформації в інформаційно-комунікаційних системах»"]},{"id":"n132","t":"law","q":"Хто є суб'єктом відносин, пов'язаних з персональними даними, і має право на надання згоди на їх обробку?","a":["Фізична особа, персональні дані якої обробляються (суб'єкт персональних даних)","Володілець бази персональних даних, що збирає та використовує інформацію для своїх цілей","Розпорядник бази персональних даних, що обробляє інформацію за дорученням володільця","Уповноважений державний орган, що здійснює контроль за дотриманням законодавства про персональні дані"]}];
